QUESTIONS.push(
/* ---------------- Organ → receptor → response ---------------- */
{id:"G2-001", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"recall",
 concept:"bladder-receptors-responses", tags:["organ"], source:"both", multi:true,
 stem:"Which pairings of a receptor on the urinary bladder and its response are CORRECT? Select all that apply.",
 options:[
  {t:"M3 on the bladder wall: contraction and urination", correct:true, why:"M3 is Gq: more Ca++ squeezes the bladder smooth muscle, so the patient urinates (the U of DUMBBELSS)."},
  {t:"β3 on the bladder wall: relaxation and retention", correct:true, why:"β3 is Gs: on bladder smooth muscle the rise in cyclic AMP relaxes the wall, so more urine is held."},
  {t:"α1 on the sphincter: contraction, no leakage", correct:true, why:"α1 is Gq: it tightens the sphincter so no urine leaks while the bladder is held relaxed."},
  {t:"M2 on the bladder wall: relaxation", correct:false, why:"M2 is the heart receptor (Gi, slower rate); the bladder wall's muscarinic receptor is M3, and it contracts."},
  {t:"β1 on the bladder wall: contraction", correct:false, why:"β1 is in the heart and kidney; the bladder's β receptor is β3, and a β receptor on smooth muscle relaxes it."}],
 teach:"The bladder carries three receptors the drugs use. M3 (parasympathetic, Gq) contracts the wall and empties the bladder, which is why bethanechol helps retention and trospium or oxybutynin helps overactivity. β3 (Gs) relaxes the wall so it holds more urine (mirabegron), and α1 (Gq) keeps the sphincter tight so nothing leaks.",
 quote:"In the bladder, we have beta 3s on the smooth muscle of the bladder, and that's going to relax the bladder so that way patients don't have to feel like urinating all the time. ... You want to relax the bladder so you can hold as much urine possible, and you want to tight the sphincter with that alpha 1, so there is no leakage coming out of it.",
 note:"One of the few select-all items here: on 10/7 he named the bladder relaxers as a select-all candidate (“Now we have a selectol”).",
 cite:"Autonomic Nervous System.pdf slides 27, 31; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/7"},

{id:"G2-002", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"recall",
 concept:"eye-receptors-responses", tags:["organ"], source:"both",
 stem:"Which pairing of a receptor in the eye and its response is CORRECT?",
 options:[
  {t:"α1 on the radial muscle: mydriasis", correct:true, why:"α1 (Gq) contracts the radial fibers, which pull the pupil open: mydriasis, the sympathetic effect that phenylephrine produces."},
  {t:"M3 on the circular muscle: mydriasis", correct:false, why:"M3 (Gq) contracts the circular muscle, which closes the pupil: miosis, the parasympathetic effect."},
  {t:"β2 in the eye: less aqueous humor production", correct:false, why:"β2 (Gs) in the eye increases the production of aqueous humor; it is β blockers that lower it."},
  {t:"M2 on the circular muscle: miosis", correct:false, why:"M2 is the heart receptor (Gi); the pupil's muscarinic receptor is M3."},
  {t:"α2 on the radial muscle: mydriasis", correct:false, why:"α2 (Gi) sits on nerve endings and in the brain and inhibits; the radial muscle is pulled open through α1."}],
 teach:"The pupil has two muscles with two receptors. The radial muscle carries α1 (Gq): the sympathetic system contracts it and the pupil dilates (mydriasis), which is what phenylephrine does and what tropicamide unmasks. The circular muscle carries M3 (Gq): the parasympathetic system contracts it and the pupil constricts (miosis). β2 (Gs) in the eye raises the production of aqueous humor.",
 quote:"In the eye, we have that dual innervation, the Musculinis wants to constrict, make the pupil small. The alpha one wants to make the pupils big. ... In the eye, it's gonna make more aqueous humor, so more liquid production inside of the eye.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 18, 42; PCOL-Cholinergic-26s.pdf slide 26; transcript 10/6; transcript 10/7"},

{id:"G2-003", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"tell",
 concept:"vessel-receptors-incorrect", tags:["organ", "incorrect"], source:"both",
 stem:"Which statement about the receptors of the arteries and veins is INCORRECT?",
 options:[
  {t:"α1 on the smooth muscle constricts the vessel", correct:false, why:"A correct statement: α1 is Gq, Ca++ rises in the smooth muscle and the vessel constricts."},
  {t:"β2 on the smooth muscle dilates the vessel", correct:false, why:"A correct statement: β2 is Gs, and on smooth muscle the cyclic AMP pathway relaxes it."},
  {t:"M3 on the vascular smooth muscle constricts the vessel", correct:true, why:"The vascular M3 is on the endothelium, not the smooth muscle: its Ca++ turns on nitric oxide synthase, and the nitric oxide dilates the vessel."},
  {t:"The sympathetic nervous system is the only autonomic innervation", correct:false, why:"A correct statement: blood vessels and kidneys receive sympathetic fibers only."},
  {t:"α1 is the predominant tone of the vessels", correct:false, why:"A correct statement: the sympathetic nerve keeps α1 partly active all the time, so the vessels are always somewhat constricted."}],
 teach:"A blood vessel has α1 and β2 on its smooth muscle and M3 on its endothelium. α1 (Gq, more Ca++) constricts and is the predominant tone because only the sympathetic nerve reaches the vessel; β2 (Gs) on the same muscle dilates. The endothelial M3 is also Gq, but its Ca++ activates nitric oxide synthase (NOS) and the nitric oxide diffuses into the muscle and dilates it, so a muscarinic agonist lowers blood pressure.",
 quote:"first thing you got to remember that the M3s RGQ, they're going to increase calcium, but because they're located in the endothelium, they're not going to constrict, the smooth muscle. They're going to relax it because they're producing the nitric oxide, OK.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 17, 29, 42, 74; Autonomic Nervous System.pdf slide 4; transcript 10/7"},

{id:"G2-004", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"tell",
 concept:"heart-receptors-incorrect", tags:["organ", "incorrect"], source:"both",
 stem:"Which statement about the receptors of the heart is INCORRECT?",
 options:[
  {t:"β1 (Gs) raises the rate and the force of contraction of the ventricles", correct:false, why:"A correct statement: norepinephrine on β1 raises cyclic AMP, and the heart beats faster and harder."},
  {t:"M2 (Gi) slows the rate", correct:false, why:"A correct statement: acetylcholine on M2 lowers cyclic AMP and opens K+ channels, the resting parasympathetic tone."},
  {t:"β1 (Gs) speeds the relaxation between beats", correct:false, why:"A correct statement: β1 also raises the rate of relaxation so the ventricles refill before the next, faster beat."},
  {t:"M3 (Gq) is the muscarinic receptor that slows the heart", correct:true, why:"The heart's muscarinic receptor is M2 (Gi); M3 is everywhere else (smooth muscle, glands, endothelium)."},
  {t:"At rest the parasympathetic M2 tone predominates", correct:false, why:"A correct statement: at rest the parasympathetic wins the cross-talk, which is why atropine raises the heart rate."}],
 teach:"The heart is dual innervated. The parasympathetic fiber releases acetylcholine onto M2 (Gi): slower rate and weaker contraction. The sympathetic fiber releases norepinephrine onto β1 (Gs): faster rate, stronger contraction and a faster rate of relaxation so the ventricle can refill. Whichever side has the predominant tone wins; at rest that is the parasympathetic.",
 quote:"We have a parasympathetic fiber releasing acetylcholine and it's slowing down your heart rate. We have a sympathetic fiber if you need to fight or flight that is going to release norepinephrine and going to speed up your heart rate. One causes bradycardia, the other causes tachycardia. One increases contractile force, the other one decreases contractile force, right?",
 cite:"Autonomic Nervous System.pdf slides 37–38; PCOL-Cholinergic-26s.pdf slide 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 40, 58; transcript 10/1; transcript 10/6"},

{id:"G2-005", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"recall",
 concept:"gi-receptors-responses", tags:["organ"], source:"both",
 stem:"Which pairing of a receptor in the gastrointestinal (GI) tract and its response is CORRECT?",
 options:[
  {t:"α2 on the parasympathetic terminal: less motility", correct:true, why:"The sympathetic norepinephrine binds α2 (Gi) on the parasympathetic nerve ending, less acetylcholine is released, the M3 receptors are not activated and motility falls (constipation)."},
  {t:"M3 on the smooth muscle: less motility", correct:false, why:"M3 (Gq) raises Ca++ in the gut muscle and increases motility and tone (diarrhea), the opposite direction."},
  {t:"α1 on the smooth muscle: more motility and diarrhea", correct:false, why:"The sympathetic receptor of the gut is α2 on the parasympathetic nerve, and the sympathetic effect is less activity, not more."},
  {t:"Nm on the smooth muscle: contraction", correct:false, why:"Nm is the skeletal muscle receptor at the neuromuscular junction; gut smooth muscle is muscarinic."},
  {t:"M2 on the parasympathetic terminal: more acetylcholine release", correct:false, why:"M2 is the heart receptor; the gut's parasympathetic terminal carries the inhibitory α2."}],
 teach:"The gut is a dual-innervation caveat. The parasympathetic fiber releases acetylcholine onto M3 (Gq, more Ca++) on the smooth muscle: more motility and secretion. The sympathetic fiber does not act on the muscle; its norepinephrine binds α2 (Gi) on the parasympathetic nerve ending and cuts acetylcholine release, so motility falls. Blocking that α2 (phenoxybenzamine) removes the brake and gives cramping and diarrhea.",
 quote:"Typically, the sympathetic inhibits the parasympathetic by releasing norepinephrine, which would bind to the alpha-2 receptor on the parasympathetic nerve. Alpha 2s are G alphai, which means they're gonna be inhibitory.",
 cite:"Autonomic Nervous System.pdf slides 45–47; transcript 10/7"},

{id:"G2-006", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"organ", skill:"tell",
 concept:"airway-receptors-incorrect", tags:["organ", "incorrect"], source:"both",
 stem:"Which statement about the receptors of the airways is INCORRECT?",
 options:[
  {t:"M3 on bronchial smooth muscle causes constriction", correct:false, why:"A correct statement: the parasympathetic acetylcholine on M3 (Gq) constricts the bronchi."},
  {t:"β2 on bronchial smooth muscle causes dilation", correct:false, why:"A correct statement: β2 (Gs) relaxes bronchial smooth muscle, which is how albuterol works."},
  {t:"A sympathetic nerve releases norepinephrine onto the bronchial β2 receptors", correct:true, why:"No sympathetic nerve reaches the lungs; the β2 receptors are there, but they are not innervated."},
  {t:"The β2 receptors are reached by epinephrine from the adrenal medulla circulating in the blood", correct:false, why:"A correct statement: the adrenal epinephrine in the blood is what activates lung β2 during fight or flight."},
  {t:"The parasympathetic nervous system is the only nerve supply", correct:false, why:"A correct statement: the lungs are the single-innervation exception on the parasympathetic side."}],
 teach:"The lungs receive a parasympathetic nerve only; its acetylcholine acts on M3 (Gq) and constricts the bronchi, which is the resting tone. The airway also carries β2 (Gs), which dilates, but no sympathetic nerve reaches it: β2 is activated by epinephrine released from the adrenal medulla into the blood, or by a β2 agonist such as albuterol.",
 quote:"So one of our exceptions that we're going to have to a rule is that in the lungs control of smooth muscle is only parasympathetic. There's no sympathetic involvement or innervation in that process, OK?",
 cite:"Autonomic Nervous System.pdf slides 23, 42–43; transcript 9/30"},

/* ---------------- Dual innervation and its exceptions ---------------- */
{id:"G2-007", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"dual", skill:"recall",
 concept:"dual-innervated-organ-heart", tags:["dual"], source:"both",
 stem:"Which organ receives both parasympathetic and sympathetic innervation?",
 options:[
  {t:"Heart", correct:true, why:"The heart has a parasympathetic fiber (acetylcholine on M2, slower) and a sympathetic fiber (norepinephrine on β1, faster): dual innervation in opposition."},
  {t:"Lungs", correct:false, why:"The lungs receive the parasympathetic nerve only; their β2 is reached by circulating epinephrine."},
  {t:"Resistance arteries", correct:false, why:"Arteries receive the sympathetic nerve only (α1 tone); their M3 is on the endothelium and is not innervated."},
  {t:"Kidneys", correct:false, why:"The kidneys receive the sympathetic nerve only (β1 → renin)."},
  {t:"Veins", correct:false, why:"Veins, like arteries, receive sympathetic fibers only (α1 → preload)."}],
 teach:"Most end organs are innervated by both divisions, which usually act in opposition: in the heart acetylcholine on M2 slows the rate while norepinephrine on β1 speeds it. The exceptions to dual innervation are the lungs (parasympathetic only) and the blood vessels and kidneys (sympathetic only).",
 quote:"for most of our organs, we have this dual innervation. We have a parasympathetic fiber releasing acetylcholine and it's slowing down your heart rate. We have a sympathetic fiber if you need to fight or flight that is going to release norepinephrine and going to speed up your heart rate.",
 cite:"Autonomic Nervous System.pdf slides 37–38, 43; transcript 10/1"},

{id:"G2-008", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"dual", skill:"tell",
 concept:"innervation-exceptions-incorrect", tags:["dual", "incorrect"], source:"both",
 stem:"Which statement about autonomic innervation is INCORRECT?",
 options:[
  {t:"The lungs receive sympathetic fibers that release norepinephrine onto β2", correct:true, why:"The lungs are parasympathetic only; no nerve releases norepinephrine in the airway, and β2 is reached by adrenal epinephrine in the blood."},
  {t:"The blood vessels receive only sympathetic innervation", correct:false, why:"A correct statement: the vessels are a sympathetic-only exception, with α1 as the predominant tone."},
  {t:"The kidneys receive only sympathetic innervation", correct:false, why:"A correct statement: the kidney is sympathetic only (β1 on the juxtaglomerular cells → renin)."},
  {t:"Both divisions increase salivation", correct:false, why:"A correct statement: the parasympathetic fiber and a sympathetic fiber (acetylcholine on M3) both make the glands secrete."},
  {t:"In the adrenal medulla the sympathetic fiber releases acetylcholine onto a nicotinic receptor", correct:false, why:"A correct statement: the adrenal medulla is the sympathetic exception where acetylcholine acts on a nicotinic receptor to release epinephrine."}],
 teach:"Three organs break the dual-innervation rule: the lungs (parasympathetic only), and the blood vessels and kidneys (sympathetic only). Two sympathetic targets break the norepinephrine rule: the adrenal medulla (acetylcholine on a nicotinic receptor, which releases epinephrine) and the salivary glands (acetylcholine on M3, so both divisions salivate).",
 quote:"So remember, parasympathetic is only in the lung, sympathetic blood vessels, and kidneys. Those are gonna be the exceptions. Everywhere else, we're gonna have this dual innervation, they're kind of oppose each other, OK?",
 cite:"Autonomic Nervous System.pdf slides 30, 43–44; transcript 10/1"},

{id:"G2-009", lecture:"L07", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"dual", skill:"recall",
 concept:"cooperating-organ-salivary", tags:["dual"], source:"both",
 stem:"In which organ do the parasympathetic and sympathetic systems act together rather than in opposition?",
 options:[
  {t:"Salivary glands", correct:true, why:"Both divisions increase salivation: the parasympathetic a fluid saliva, the sympathetic (acetylcholine on M3) a thick one."},
  {t:"Heart", correct:false, why:"Opposition: M2 slows the heart, β1 speeds it."},
  {t:"Eye", correct:false, why:"Opposition: M3 constricts the pupil, α1 dilates it."},
  {t:"Gastrointestinal (GI) tract", correct:false, why:"Opposition: M3 increases motility, the sympathetic α2 on the parasympathetic terminal decreases it."},
  {t:"Lungs", correct:false, why:"No cooperation possible: the lungs receive the parasympathetic nerve only."}],
 teach:"In most dual-innervated organs the two divisions function in opposition (heart, eye, gut). The exceptions are the salivary glands, where both divisions cause salivation, and the male sex organ, where the parasympathetic produces the erection and the sympathetic the ejaculation (point and shoot).",
 quote:"So when it comes to salivation, both parasympathetic and sympathetic increased salivation. The difference is what kind of gland they activate. ... So a way for you to remember that in the exam is just point and shoot, right. A point for parasympathetic and shoot for sympathetic.",
 cite:"Autonomic Nervous System.pdf slide 44; transcript 10/1"},

/* ---------------- G protein by drug (his Jeopardy form) ---------------- */
{id:"G2-010", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"gprot", skill:"recall",
 concept:"drugs-activating-gs", tags:["g-protein", "all-above"], source:"both",
 stem:"Which of the following drugs activates the Gs pathway?",
 options:[
  {t:"Dobutamine", correct:false, why:"A Gs activator (β1 agonist), but not the only one here."},
  {t:"Albuterol", correct:false, why:"A Gs activator (β2 agonist), but not the only one here."},
  {t:"Mirabegron", correct:false, why:"A Gs activator (β3 agonist), but not the only one here."},
  {t:"Isoproterenol", correct:false, why:"A Gs activator (β1 and β2 agonist), but not the only one here."},
  {t:"All the above", correct:true, why:"Every β receptor (β1, β2, β3) is linked to Gs, so every β agonist activates adenylate cyclase and raises cyclic AMP."}],
 teach:"All three β receptors couple to Gs: activation of adenylate cyclase and more cyclic AMP (cAMP). So any β agonist, whether it is selective for β1 (dobutamine), β2 (albuterol), β3 (mirabegron) or non-selective (isoproterenol), activates the Gs pathway. What differs is the location: β1 in the heart and kidney, β2 on smooth muscle, β3 in the bladder.",
 quote:"it doesn't matter if it's a beta 1, a beta 2, or beta 3, they are all linked to GS, which means they're going to stimulate. The difference over here is the location and the function they're going to have, OK.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 40, 42, 44–45; transcript 10/7"},

{id:"G2-011", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"gprot", skill:"recall",
 concept:"drug-activating-gi", tags:["g-protein"], source:"both",
 stem:"Which of the following drugs activates the Gi pathway?",
 options:[
  {t:"Clonidine", correct:true, why:"An α2 agonist; α2 is coupled to Gi, so the drug inhibits adenylate cyclase, lowers cyclic AMP and suppresses norepinephrine release."},
  {t:"Phenylephrine", correct:false, why:"An α1 agonist: it activates Gq, not Gi."},
  {t:"Dobutamine", correct:false, why:"A β1 agonist: it activates Gs."},
  {t:"Prazosin", correct:false, why:"An α1 antagonist: it blocks the Gq pathway rather than activating any."},
  {t:"Atropine", correct:false, why:"A muscarinic antagonist: it blocks M2 (Gi) and M1/M3 (Gq); it activates nothing."}],
 teach:"Clonidine is an agonist, but the receptor it activates, α2, is coupled to Gi (inhibitory): adenylate cyclase is inhibited, cyclic AMP (cAMP) falls and norepinephrine release is suppressed. That is why an agonist lowers sympathetic tone and blood pressure. Among the adrenergic receptors only α2 is Gi; α1 is Gq and all β receptors are Gs.",
 quote:"Remember, clonidine is an agonist to the alpha 2, but it is an inhibitory. Pathway. So that's gonna decrease blood pressure, cardiac output, and the sympathetic outflow as an overall process.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 21, 23; transcript 10/6"},

{id:"G2-012", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"gprot", skill:"recall",
 concept:"drug-inhibiting-gs", tags:["g-protein"], source:"both",
 stem:"Which of the following drugs inhibits the Gs pathway?",
 options:[
  {t:"Metoprolol", correct:true, why:"A β1 antagonist; β1 is coupled to Gs, so blocking it stops adenylate cyclase from being activated and cyclic AMP in the heart falls."},
  {t:"Clonidine", correct:false, why:"An α2 agonist: it activates Gi, which lowers cyclic AMP by a different route (inhibition of the enzyme), and it does not touch a Gs receptor."},
  {t:"Prazosin", correct:false, why:"An α1 antagonist: it blocks a Gq receptor, so it lowers Ca++, not cyclic AMP."},
  {t:"Mirtazapine", correct:false, why:"An α2 antagonist (plus H1, muscarinic and α1 block): it removes a Gi brake, so norepinephrine release rises."},
  {t:"Carbachol", correct:false, why:"A muscarinic agonist: it activates Gq (M1, M3) and Gi (M2), and inhibits no Gs receptor."}],
 teach:"Every β receptor is linked to Gs, and every β blocker blocks β1. So metoprolol, by occupying the cardiac β1, prevents the activation of adenylate cyclase: less cyclic AMP (cAMP), lower rate, lower contractility, lower renin. The other options either activate a pathway (clonidine Gi, carbachol Gq/Gi) or block a Gq or Gi receptor (prazosin, mirtazapine).",
 quote:"That all beta blockers, depending if they are selective or not, they're going to block beta ones. ... it doesn't matter if it's a beta 1, a beta 2, or beta 3, they are all linked to GS, which means they're going to stimulate.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 40, 54; transcript 10/7"},

{id:"G2-013", lecture:"L09", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"gprot", skill:"recall",
 concept:"drugs-raising-calcium-gq", tags:["g-protein", "all-above"], source:"both",
 stem:"Which of the following drugs increases intracellular Ca++ through the Gq pathway?",
 options:[
  {t:"Phenylephrine", correct:false, why:"An α1 agonist (Gq → PLC → IP3 → Ca++), but not the only one here."},
  {t:"Carbachol", correct:false, why:"A muscarinic agonist at M1 and M3 (both Gq), but not the only one here."},
  {t:"Pilocarpine", correct:false, why:"A muscarinic agonist at M1 and M3 (Gq), but not the only one here."},
  {t:"Bethanechol", correct:false, why:"A muscarinic agonist at M1 and M3 (Gq), but not the only one here."},
  {t:"All the above", correct:true, why:"α1, M1 and M3 are all coupled to Gq: phospholipase C makes inositol triphosphate (IP3), which releases Ca++, so every agonist at these receptors raises Ca++."}],
 teach:"Gq is shared by α1, M1 and M3: the receptor activates phospholipase C (PLC), which makes inositol triphosphate (IP3), and IP3 releases Ca++ from the endoplasmic reticulum. An agonist at any of them raises Ca++: phenylephrine at α1 (vasoconstriction, mydriasis) and carbachol, pilocarpine or bethanechol at M3 (bronchoconstriction, gut and bladder contraction, secretion). Jeopardy asked the mirror question, which drugs inhibit Gq: prazosin, phenoxybenzamine, atropine and losartan.",
 quote:"it's an agonist to the alpha 1, so it's gonna activate it and it's gonna activate the GQ pathway which is gonna increase calcium inside of those smooth muscles which leads to vasoconstriction, right. ... what is carbocol? Is a It's an agonist, selective or non-selective. If it binds to more than one receptor, it's non-selective because it activates the M1s, M2s, and the M3s, right?",
 cite:"PCOL-Cholinergic-26s.pdf slides 6, 9, 11; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 17–18; Autonomic Nervous System.pdf slide 4; transcript 10/6"},


/* ---------------- Tier 1: predict the effect of a receptor, in his poll form ---------------- */
{id:"G2-014", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"beta2-activation-bronchodilation", tags:["tier1"], source:"both",
 stem:"Activation of β2 adrenergic receptors is most likely to produce:",
 options:[
  {t:"Bronchial dilation", correct:true, why:"β2 is Gs: on bronchial smooth muscle the rise in cyclic AMP relaxes the muscle and the airways open."},
  {t:"Bradycardia", correct:false, why:"A slower heart comes from M2 (Gi) or from blocking β1; β agonists speed the heart."},
  {t:"Vasoconstriction", correct:false, why:"Vessels constrict through α1 (Gq); β2 on vascular smooth muscle dilates."},
  {t:"Miosis", correct:false, why:"A small pupil comes from M3 on the circular muscle; β2 in the eye makes more aqueous humor."},
  {t:"Increased GI motility", correct:false, why:"Gut motility rises through M3 (Gq); a β receptor on smooth muscle relaxes it."}],
 teach:"β2 is coupled to Gs and raises cyclic AMP (cAMP), but on smooth muscle that pathway relaxes rather than contracts. So β2 activation dilates the bronchi (albuterol), dilates blood vessels and relaxes the bladder. In the brain it excites and in the eye it increases aqueous humor production.",
 quote:"beta 2 activation on the mood muscle of your lungs, bronchodilate, of your blood vessels, vasodilate, on your bladder, vasodilate, OK?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 42; transcript 10/7"},

{id:"G2-015", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"beta1-blockade-bradycardia", tags:["tier1"], source:"both",
 stem:"Blockade of β1 adrenergic receptors is most likely to produce:",
 options:[
  {t:"Bradycardia", correct:true, why:"With β1 blocked, norepinephrine cannot speed the heart and the parasympathetic M2 tone takes over: the rate falls."},
  {t:"Tachycardia", correct:false, why:"A faster heart is the β1 agonist effect (or the reflex to a vasodilator); the antagonist does the opposite."},
  {t:"Bronchial dilation", correct:false, why:"The airways carry β2, not β1; and blocking a β receptor would constrict, not dilate."},
  {t:"Mydriasis", correct:false, why:"The pupil dilates through α1; β1 is in the heart and kidney."},
  {t:"Increased renin release", correct:false, why:"β1 on the juxtaglomerular cells releases renin; blocking it lowers renin."}],
 teach:"β1 (Gs) in the heart raises rate, contractility and the rate of relaxation, and in the kidney it releases renin. Every β blocker blocks β1, so every β blocker lowers cardiac output and renin; the resting parasympathetic tone on M2 is left unopposed and the heart slows. The lungs are untouched unless the blocker also hits β2.",
 quote:"So if I block the ability of my norepinephrine to bind and activate the beta ones, because all beta blockers blocks beta ones, who's gonna take over? Parasympathetic. So you're gonna get what? Bradycardia, right?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 56, 58; transcript 10/7"},

{id:"G2-016", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"beta3-activation-retention", tags:["tier1"], source:"both",
 stem:"Activation of β3 adrenergic receptors is most likely to produce:",
 options:[
  {t:"Decreased urination", correct:true, why:"β3 (Gs) on the bladder smooth muscle relaxes it, so the bladder holds more urine and the patient urinates less."},
  {t:"Increased urination", correct:false, why:"Urination follows M3 contraction of the bladder wall; β3 relaxes it."},
  {t:"Bronchial constriction", correct:false, why:"Bronchi constrict through M3; a β receptor on smooth muscle relaxes."},
  {t:"Tachycardia", correct:false, why:"The heart's β receptor is β1; β3 has its greatest effect in the bladder."},
  {t:"Salivation", correct:false, why:"Salivation is an M3 effect of the glands; β3 is in the bladder."}],
 teach:"β3 couples to Gs and cyclic AMP (cAMP) like the other β receptors, and its site of action is the bladder: activation relaxes the detrusor muscle and increases bladder capacity, so voiding is prevented. Mirabegron, the β3 agonist, relieves overactive bladder without the anti-DUMBBELSS effects of the antimuscarinics.",
 quote:"In the bladder, we have beta 3s on the smooth muscle of the bladder, and that's going to relax the bladder so that way patients don't have to feel like urinating all the time.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/7"},

{id:"G2-017", lecture:"L10", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"alpha2-gut-constipation", tags:["tier1"], source:"both",
 stem:"Activation of the α2 receptors on the parasympathetic nerve endings of the gut is most likely to produce:",
 options:[
  {t:"Constipation", correct:true, why:"α2 is Gi on the parasympathetic terminal: less acetylcholine is released, the M3 receptors on the gut are not activated and motility falls."},
  {t:"Diarrhea", correct:false, why:"Diarrhea is the M3 (Gq) effect of more acetylcholine; α2 cuts the acetylcholine release."},
  {t:"Increased salivation", correct:false, why:"Salivation is an M3 gland effect; the gut α2 lowers parasympathetic output to the gut."},
  {t:"Bronchial constriction", correct:false, why:"Bronchi constrict through M3 in the lungs; these α2 receptors sit on the gut's parasympathetic nerves."},
  {t:"Vomiting", correct:false, why:"Emesis is a central M1 effect of muscarinic agonists; α2 activation is inhibitory."}],
 teach:"In the gut the sympathetic system works through α2 (Gi) on the parasympathetic nerve ending: less cyclic AMP, less acetylcholine release, fewer M3 receptors activated, so motility and tone fall. This is why clonidine, an α2 agonist, causes constipation, and why phenoxybenzamine, which blocks α2, causes cramping and diarrhea.",
 quote:"That by suppressing acetylcholine release, we don't activate the M3s and thus we don't get the increase in motility in tone. We're gonna get constipation.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 21, 26; Autonomic Nervous System.pdf slides 45–47; transcript 10/6"},

{id:"G2-018", lecture:"L10", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"alpha1-antagonist-sphincter-voiding", tags:["tier1"], source:"both",
 stem:"An α1 antagonist reaches the sphincter of the bladder and the vessels around the prostate. Which effect is most likely?",
 options:[
  {t:"Easier urination", correct:true, why:"α1 (Gq) keeps the sphincter and the prostate vessels contracted; blocking it relaxes them, so urine passes more easily."},
  {t:"Urinary retention", correct:false, why:"Retention follows α1 activation (tight sphincter) or β3 relaxation of the wall, not α1 blockade."},
  {t:"Contraction of the bladder wall", correct:false, why:"The bladder wall contracts through M3; α1 is on the sphincter, not the detrusor."},
  {t:"Mydriasis", correct:false, why:"The pupil dilates through α1 activation; an α1 antagonist leaves the pupil small."},
  {t:"Vasoconstriction of the prostate vessels", correct:false, why:"α1 activation constricts those vessels; the antagonist relaxes them."}],
 teach:"α1 receptors sit on the bladder sphincter and on the blood vessels of the prostate and urethra (the “urine” in “I see and smell bloody urine”). The sympathetic tone on them keeps the outlet tight so nothing leaks. An α1 antagonist such as prazosin or tamsulosin relaxes the sphincter and those vessels, which makes urination easier for a patient with an enlarged prostate.",
 quote:"we're gonna be talking about uh alpha one antagonist for the treatment of enlarged prostate, because by relaxing those blood vessels, we can facilitate your patient's urination. As well as relaxing the sphincter of the bladder. ... You want to relax the bladder so you can hold as much urine possible, and you want to tight the sphincter with that alpha 1, so there is no leakage coming out of it.",
 note:"ANS slide 31: “Urination — Sphincter (α1) and bladder smooth muscle (β3)”. The benign prostatic hyperplasia use itself is for the renal module; only the receptor effect is asked.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 17, 28; Autonomic Nervous System.pdf slide 31; transcript 10/6; transcript 10/7"},

{id:"G2-019", lecture:"L09", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"least-likely-raise-heart-rate", tags:["tier1", "least-likely"], source:"both",
 stem:"Which of the following drugs is LEAST likely to increase heart rate?",
 options:[
  {t:"Carbachol", correct:true, why:"A muscarinic agonist on cardiac M2 (Gi): it slows the heart, the opposite direction."},
  {t:"Atropine", correct:false, why:"Blocks M2 and removes the resting parasympathetic tone: tachycardia."},
  {t:"Isoproterenol", correct:false, why:"A β1 (and β2) agonist: more cyclic AMP in the heart, faster rate."},
  {t:"Dobutamine", correct:false, why:"A selective β1 agonist: faster and stronger beats."},
  {t:"Prazosin", correct:false, why:"It dilates the arteries; the baroreceptors answer the fall in pressure with reflex tachycardia."}],
 teach:"Heart rate rises when β1 is activated (isoproterenol, dobutamine), when the parasympathetic M2 tone is blocked (atropine), or as a baroreceptor reflex to a vasodilator (prazosin, phenoxybenzamine). A muscarinic agonist such as carbachol does the opposite: M2 (Gi) slows the heart, which is why atropine, not carbachol, treats severe bradycardia.",
 quote:"Why is carbachol not the best answer? Because that's a muscularic agonist, we're gonna activate the M2s, which are GI, so you're gonna inhibit even more. You're gonna stop their heart. ... What about if it's the alpha ones in the arteries? If you vasodilate the arteries, now your barrels are gonna sense my blood pressure is too low. What is it gonna do? I'm gonna increase the sympathetic, I'm gonna get reflex tachycardia, so palpitations, right?",
 cite:"PCOL-Cholinergic-26s.pdf slides 7, 19; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 30, 41, 45; transcript 10/6"},

{id:"G2-020", lecture:"L09", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"least-likely-dry-mouth", tags:["tier1", "least-likely"], source:"both",
 stem:"Which of the following drugs is LEAST likely to cause dry mouth?",
 options:[
  {t:"Pilocarpine", correct:true, why:"A muscarinic agonist on the glands' M3: it increases salivation and is used for dry mouth."},
  {t:"Atropine", correct:false, why:"Blocks the glands' M3: no secretion, dry mouth (anti-DUMBBELSS)."},
  {t:"Clonidine", correct:false, why:"Suppresses the sympathetic outflow to the salivary gland; about 40% of patients complain of dry mouth."},
  {t:"Oxybutynin", correct:false, why:"A bladder antimuscarinic that also blocks the glands' M3: xerostomia is shared by the whole group."},
  {t:"Mirtazapine", correct:false, why:"Among its targets it blocks muscarinic receptors, so patients get xerostomia and constipation."}],
 teach:"Dry mouth has two routes. Muscarinic blockade (atropine, oxybutynin and the other bladder drugs, mirtazapine) stops the M3-driven secretion of the glands. Clonidine dries the mouth by suppressing the sympathetic outflow, since the sympathetic fiber to the salivary gland also drives salivation. A muscarinic agonist such as pilocarpine does the opposite and is given to make patients salivate.",
 quote:"Do you know what is one of the major complaints of patients taking clonidine? Dry mouth. Because you suppress the sympathetic to the salivary gland, and they're going to get dry mouth.",
 cite:"PCOL-Cholinergic-26s.pdf slides 14, 30, 32; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 26, 33; transcript 10/6"},

{id:"G2-021", lecture:"L10", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"least-likely-constipation", tags:["tier1", "least-likely"], source:"both",
 stem:"Which of the following drugs is LEAST likely to cause constipation?",
 options:[
  {t:"Phenoxybenzamine", correct:true, why:"It blocks the α2 on the parasympathetic nerves of the gut, removing the brake on acetylcholine release: cramping and diarrhea, not constipation."},
  {t:"Atropine, the muscarinic antagonist", correct:false, why:"Blocks the gut's M3: less motility and tone, constipation (anti-DUMBBELSS)."},
  {t:"Clonidine, the α2 agonist", correct:false, why:"Activates the gut α2 (Gi): less acetylcholine released, less M3 activation, constipation."},
  {t:"Trospium, the bladder antimuscarinic", correct:false, why:"A bladder antimuscarinic that also blocks gut M3: constipation is shared by the whole group."},
  {t:"Mirtazapine, the α2 antagonist", correct:false, why:"Its muscarinic blockade gives xerostomia and constipation."}],
 teach:"Gut motility is driven by acetylcholine on M3. It falls, and constipation follows, when M3 is blocked (atropine, trospium, mirtazapine) or when acetylcholine release is cut by an α2 agonist (clonidine). Phenoxybenzamine goes the other way: by blocking α2 irreversibly it takes away the sympathetic inhibition of the parasympathetic nerve, so the gut is over-stimulated.",
 quote:"However, phenoxybenzamine is an irreversible alpha 2 antagonist. So if I block that, I take away the inhibition. Now too much parasympathetic tone, cramping, diarrhea, and so on.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 26, 33, 36; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/7"},

{id:"G2-022", lecture:"L09", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"least-likely-mydriasis", tags:["tier1", "least-likely"], source:"both",
 stem:"Which of the following drugs is LEAST likely to dilate the pupil?",
 options:[
  {t:"Pilocarpine", correct:true, why:"A muscarinic agonist on the circular muscle's M3: the pupil constricts (miosis)."},
  {t:"Phenylephrine", correct:false, why:"An α1 agonist on the radial muscle: the fibers pull the pupil open."},
  {t:"Atropine", correct:false, why:"Blocks M3 on the circular muscle; the sympathetic α1 pull is unopposed and the pupil dilates."},
  {t:"Tropicamide", correct:false, why:"An atropine-like antagonist used in eye examinations for exactly this: pupil dilation."},
  {t:"Scopolamine", correct:false, why:"A non-selective muscarinic antagonist: anti-DUMBBELSS includes a dilated pupil."}],
 teach:"The pupil dilates either by activating α1 on the radial muscle (phenylephrine) or by blocking M3 on the circular muscle so the sympathetic pull is unopposed (atropine, tropicamide, scopolamine). A muscarinic agonist such as pilocarpine contracts the circular muscle and the pupil gets smaller; so does phenoxybenzamine, by blocking α1.",
 quote:"if activate the alpha 1 is in the eyes, they are in these transverse fibers, so we're going to pull them apart by constricting and you're going to get pupil dilation, also known as madriasis, right? ... In the eye, we have that dual innervation, the Musculinis wants to constrict, make the pupil small. The alpha one wants to make the pupils big. So we're gonna get pupil dilation on that process.",
 cite:"PCOL-Cholinergic-26s.pdf slides 13, 26; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 18; transcript 10/6"},

{id:"G2-023", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"apply",
 concept:"sa-node-dysfunction-beta-blocker", tags:["tier1", "scenario"], source:"both",
 stem:"If your patient has sinoatrial (SA) node dysfunction with a very low resting heart rate and is started on propranolol, which of the following is most likely?",
 options:[
  {t:"Excessive bradycardia", correct:true, why:"All β blockers block β1; with the pacemaker already slow, the parasympathetic takes over at night and the rate can fall until the heart stops."},
  {t:"Reflex tachycardia from the baroreceptors", correct:false, why:"That follows vasodilators that drop the pressure; a β blocker lowers the rate directly."},
  {t:"Bronchial dilation", correct:false, why:"Propranolol blocks β2 as well, which narrows, not widens, the airways."},
  {t:"A hypertensive crisis", correct:false, why:"That is the risk of stopping a β blocker abruptly after up-regulation, not of starting one."},
  {t:"Increased renin release", correct:false, why:"β1 blockade in the juxtaglomerular cells lowers renin."}],
 teach:"Every β blocker lowers heart rate by blocking the cardiac β1, leaving the parasympathetic M2 tone unopposed. A patient whose sinoatrial (SA) or atrioventricular (AV) node already fires too slowly can be pushed into excessive bradycardia, especially at night when the parasympathetic takes over. His rationale for such a patient is pindolol, the partial agonist, which keeps the rate up at rest and still outcompetes norepinephrine when awake.",
 quote:"so you want to be careful giving them a beta blocker, because at night, what happens? You go to sleep, your parasympathetic takes over. Heart rate gets even lower, and the heart may stop.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 55, 59; transcript 10/7"},

{id:"G2-024", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"epinephrine-with-lidocaine", tags:["ddi"], source:"both",
 stem:"Epinephrine is mixed with lidocaine when a cut is sutured. Which of the following is most likely?",
 options:[
  {t:"Less bleeding, and lidocaine stays at the site", correct:true, why:"The cutaneous vessels carry α1; epinephrine constricts them, so the wound bleeds less and the anesthetic is not carried into the bloodstream."},
  {t:"More bleeding from β2 dilation of the skin vessels", correct:false, why:"At the dose used the α1 constriction of the cutaneous vessels is the effect; it reduces bleeding."},
  {t:"Lidocaine reaches the heart faster", correct:false, why:"Constricted vessels slow the systemic spread; the point is to keep lidocaine away from the heart, where it could cause arrhythmias."},
  {t:"The wound muscles relax through β2", correct:false, why:"Skeletal muscle is not the target; the useful receptor is α1 on the skin vessels."},
  {t:"No interaction: skin vessels have no adrenergic receptors", correct:false, why:"Cutaneous blood vessels have α1, which is why a vasoconstrictor is added at all."}],
 teach:"Cutaneous blood vessels carry α1. Adding epinephrine (or cocaine) to lidocaine constricts them: the suture site bleeds less, and the local anesthetic stays local instead of dissolving into the bloodstream, where lidocaine could reach the heart and cause arrhythmias. This is a wanted drug–drug interaction built on the site of action of α1.",
 quote:"We can use that with lido. to decrease the bleeding at a local site when you're suturing a patient or perhaps to decrease the, you know, the drug from dissolving into the bloodstream",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 52; transcript 10/7"},

{id:"G2-025", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"t1", skill:"tell",
 concept:"albuterol-partial-vs-laba-full", tags:[], source:"both",
 stem:"Which statement about the β2 agonists is CORRECT?",
 options:[
  {t:"Albuterol is a partial agonist; salmeterol and formoterol are full agonists", correct:true, why:"He placed albuterol as the partial agonist and the long-acting salmeterol and formoterol as full agonists, which is why they give more effect when it is needed."},
  {t:"Salmeterol is the rescue inhaler", correct:false, why:"The rescue drug is albuterol, the short-acting one; salmeterol and formoterol are long acting."},
  {t:"Albuterol activates β1 in the lungs", correct:false, why:"The airway receptor is β2; a -terol is a β2 agonist."},
  {t:"Formoterol is short acting", correct:false, why:"Formoterol is one of the long-acting β2 agonists (LABA)."},
  {t:"Levalbuterol, the purified isomer, gives a clinically better outcome than albuterol", correct:false, why:"Levalbuterol is the isomer with the potency, but clinically the outcome is the same, so there is no reason to pay more."}],
 teach:"Every “-terol” is a β2 agonist, and that class identification is what he needs. Within the class, albuterol (the short-acting rescue drug) is a partial agonist, while salmeterol and formoterol are full agonists and also long acting. Levalbuterol is the active isomer of albuterol, but clinically it makes no difference.",
 quote:"Albuterol, it is a partial agonist, as salmeterol and fumeterol are a full agonist, and they're also long acting. So if you really need the bang for your buck, that's why we're gonna go with it.",
 note:"He added: “If you know that a terol is a beta2 agonist, that's good for me. It doesn't matter if it's short acting or long acting.” The partial/full distinction was taught but is secondary to the class.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 42–43; transcript 10/7"},


/* ---------------- Tier 2: two drugs together (the good and the bad) ---------------- */
{id:"G2-026", lecture:"L10", prof:"Gottlieb", tier:"new", level:2, ladder:"prazosin", ladderName:"Prazosin, norepinephrine and phenoxybenzamine", topic:"GAP2", sub:"t2", skill:"apply",
 concept:"prazosin-plus-beta-blocker", tags:["ddi"], source:"both",
 stem:"A patient on prazosin for hypertension complains of palpitations. Which drug would most likely be added to control them?",
 options:[
  {t:"Metoprolol", correct:true, why:"The palpitations are a reflex tachycardia through β1; a β blocker blocks it, which is why prazosin is not used alone."},
  {t:"Phenylephrine", correct:false, why:"An α1 agonist would outcompete prazosin and raise the pressure back up: it undoes the treatment."},
  {t:"Atropine", correct:false, why:"Blocking M2 removes the parasympathetic brake and makes the heart even faster."},
  {t:"A second α1 antagonist", correct:false, why:"More vasodilation drops the pressure further and the baroreceptors drive the heart faster still."},
  {t:"Cocaine", correct:false, why:"More norepinephrine in the synapse would raise the pressure and the heart rate; it is the wrong direction on both."}],
 teach:"Prazosin dilates the arteries and veins; the baroreceptors sense the fall in pressure, shut off the parasympathetic and increase the sympathetic, so the heart speeds up (reflex tachycardia, felt as palpitations). Because of this compensation prazosin is a poor monotherapy; a β blocker is added to block the β1-driven tachycardia. This is a good drug–drug interaction: one drug covers the side effect of the other.",
 quote:"So it's not a really drug, a really good drug to use as a monotherapy, but you're gonna have to add like a beta blocker to block the tachycardia.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 30; transcript 10/6"},

{id:"G2-027", lecture:"L09", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"two-muscarinic-agonists-additive", tags:["ddi"], source:"both",
 stem:"A patient taking bethanechol for urinary retention is also given pilocarpine for dry mouth. Which outcome is most likely?",
 options:[
  {t:"More DUMBBELSS: the two agonists add up", correct:true, why:"Both are non-selective muscarinic agonists; two agonists on the same receptors push the system the same way, so the patient gets a lot of DUMBBELSS."},
  {t:"Pilocarpine outcompetes bethanechol at M3", correct:false, why:"Outcompeting is what an antagonist does to an agonist; two agonists both activate the receptor."},
  {t:"No interaction: they act on different receptors", correct:false, why:"Both act on M1, M2 and M3; the targets are the same."},
  {t:"Anti-DUMBBELSS from the combination", correct:false, why:"Anti-DUMBBELSS needs a muscarinic antagonist; neither drug blocks anything."},
  {t:"Bethanechol blocks pilocarpine at the nicotinic receptors", correct:false, why:"Neither drug touches nicotinic receptors; the muscarinic agonists are selective for muscarinic receptors."}],
 teach:"Bethanechol and pilocarpine are both reversible, non-selective muscarinic agonists (M1, M2, M3). Each alone gives DUMBBELSS; given together they add up, so the patient gets diarrhea, urination, miosis, bradycardia, bronchoconstriction, emesis, lacrimation, salivation and stimulation in excess. The same additive rule applies when a cholinesterase inhibitor is added to a muscarinic agonist.",
 quote:"What would be a possible drug-drug interaction? Well, if add another agonist, now you're really gonna get a lot of dumbbells, right? Or if we add one of those acetylcholesterase enzyme antagonists, because now we even have more acetylcholine on board, that's gonna be bad. That's gonna be very unpleasant.",
 cite:"PCOL-Cholinergic-26s.pdf slides 11–13; transcript 10/6"},

{id:"G2-028", lecture:"L08", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"varenicline-plus-nicotine", tags:["ddi"], source:"both",
 stem:"A patient on varenicline smokes a cigarette. Which of the following is most likely?",
 options:[
  {t:"The patient feels the full nicotine effect; varenicline is displaced", correct:false, why:"Varenicline has high affinity for the α4/β2 receptor; it is nicotine that is kept from binding, so the effect is reduced, not full."},
  {t:"Nicotine's effect is kept down by the partial agonist", correct:true, why:"Varenicline, a high-affinity partial agonist, occupies the α4/β2 neuronal nicotinic receptors; nicotine, the full agonist, cannot produce its full effect."},
  {t:"Nicotine and varenicline add up to a stronger effect", correct:false, why:"A partial agonist in the presence of a full agonist lowers the response; the two do not add."},
  {t:"Varenicline blocks nicotine at the ganglionic Nn receptors", correct:false, why:"Varenicline is selective for the central α4/β2 receptors; the ganglia use the α3 combinations."},
  {t:"Nicotine displaces varenicline and the craving returns fully", correct:false, why:"Varenicline has high affinity for the receptor; it is nicotine that is kept from binding."}],
 teach:"Varenicline is a high-affinity partial agonist at the α4/β2 neuronal nicotinic (Nn) receptor in the brain. With no nicotine around it activates the receptor a little and prevents withdrawal; when the patient smokes, it competes with nicotine, the full agonist, and keeps the nicotine effect down. Adding nicotine (a cigarette, a patch or gum) to varenicline is therefore the drug–drug interaction to be careful about.",
 quote:"It's a partial agonist. We want to maintain a lab with just enough so they don't go into withdrawal, but if they decide to smoke, it's going to compete with nicotine, which is the full agonist, and it's going to keep it down, right?",
 note:"The first option is marked wrong only because the second states the mechanism fully; on his exam the two would not both appear. He asked the class: “What would be a drug-drug interaction with Chantix or V and Klein? What if they're smoking?”",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 7–8; transcript 10/5"},

{id:"G2-029", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"dobutamine-plus-metoprolol", tags:["ddi"], source:"both",
 stem:"A patient on metoprolol is given dobutamine for a failing heart. Which outcome is most likely?",
 options:[
  {t:"Metoprolol outcompetes dobutamine at β1", correct:true, why:"Both are reversible at the cardiac β1; the antagonist already on board outcompetes the agonist, so the rise in contractility and rate is blunted (a negative drug–drug interaction)."},
  {t:"The two add up to a larger rise in cardiac output", correct:false, why:"Effects add up only when both drugs push the same way; the antagonist pushes against the agonist."},
  {t:"Dobutamine outcompetes metoprolol at β2", correct:false, why:"Dobutamine is β1 selective and metoprolol blocks β1; β2 is not where they meet."},
  {t:"No interaction: they act at different sites", correct:false, why:"Both act on the β1 receptor of the heart; one activates it, the other blocks it."},
  {t:"Metoprolol speeds the breakdown of dobutamine", correct:false, why:"Metoprolol is a receptor antagonist; it does not act on any enzyme."}],
 teach:"Dobutamine is the selective β1 agonist and metoprolol the selective β1 antagonist, the pair on the β1 slide. Given together they compete for the same receptor: the antagonist outcompetes the agonist and defeats its purpose, so dobutamine needs a higher dose to raise cardiac output. His rule for any agonist: adding its antagonist is the negative drug–drug interaction.",
 quote:"So these two drugs are, one is a selective beta 1 agonist in green, the top one, the buttamine, metoprolol is a selective beta 1 antagonist. ... What would be a negative drug-drug interaction? If you add an antagonist to outcompete it, so you're defeating the purpose.",
 note:"He paired the two drugs on slide 40 and stated the agonist-plus-antagonist rule for carbachol on 10/6; the two were not combined aloud. Keyed from the rule.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 40–41; transcript 10/7; transcript 10/6"},

{id:"G2-030", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, ladder:"nitroglycerin", ladderName:"Nitroglycerin and sildenafil", topic:"GAP2", sub:"t2", skill:"apply",
 concept:"nitrate-plus-pde-inhibitor-mechanism", tags:["ddi", "exam-cue"], source:"both",
 stem:"A patient taking isosorbide mononitrate also takes tadalafil. Which of the following is most likely?",
 options:[
  {t:"Marked hypotension: cGMP builds up with no PDE to clear it", correct:true, why:"The nitrate donates nitric oxide and makes more cyclic GMP; tadalafil blocks the phosphodiesterase that breaks it down, so the two vasodilations add and the pressure drops dangerously."},
  {t:"Hypertensive crisis: both drugs activate α1 receptors", correct:false, why:"Neither drug touches α1; both lower vascular tone."},
  {t:"No interaction: tadalafil acts only in the penis", correct:false, why:"Phosphodiesterase is in blood vessels throughout the body (and the eye), so the effect on cyclic GMP is systemic."},
  {t:"Tadalafil donates extra nitric oxide, doubling the nitrate dose", correct:false, why:"Tadalafil donates nothing; it blocks the breakdown of cyclic GMP."},
  {t:"The nitrate blocks the phosphodiesterase and tadalafil activates guanylyl cyclase, raising cAMP", correct:false, why:"The roles are reversed, and the messenger is cyclic GMP, not cyclic AMP."}],
 teach:"A nitrate (nitroglycerin, isosorbide mononitrate, nitroprusside) releases nitric oxide, which activates soluble guanylyl cyclase (sGC) and raises cyclic GMP (cGMP) in vascular smooth muscle: vasodilation. Phosphodiesterase (PDE) is what ends the signal by breaking cGMP down. Sildenafil, tadalafil and vardenafil block PDE, so with a nitrate on board the cGMP keeps rising: an additive vasodilation and a marked, unsafe drop in blood pressure.",
 quote:"But the key thing over here is we have a very bad drug-drug interaction. And I would like for you to tell me on an exam is why it's bad to take Sadenophil with a nitric oxide donor, right? Because you have this additive effect to the drugs.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 62, 74; transcript 10/7"},

{id:"G2-031", lecture:"L09", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"cholinesterase-inhibitor-plus-antimuscarinic", tags:["ddi"], source:"both",
 stem:"A patient with Alzheimer's disease on rivastigmine is started on trospium for an overactive bladder. Which interaction is most likely?",
 options:[
  {t:"Trospium outcompetes the extra acetylcholine at M3", correct:true, why:"Rivastigmine raises acetylcholine everywhere; trospium, a reversible muscarinic antagonist, blocks the M3 that acetylcholine would activate, so the two work against each other (less DUMBBELSS, less of each drug's effect)."},
  {t:"The two add up to more DUMBBELSS", correct:false, why:"Adding up needs two drugs pushing the same way; an antagonist pushes against the extra acetylcholine."},
  {t:"Trospium blocks rivastigmine at the enzyme", correct:false, why:"Trospium binds the muscarinic receptor, not acetylcholinesterase."},
  {t:"Rivastigmine reverses trospium at the nicotinic receptors", correct:false, why:"Trospium has affinity only for muscarinic receptors; nicotinic receptors are not where they meet."},
  {t:"No interaction: rivastigmine acts only in the brain", correct:false, why:"Rivastigmine inhibits the enzyme anywhere acetylcholine is released, the bladder included."}],
 teach:"A cholinesterase inhibitor such as rivastigmine raises acetylcholine throughout the body, which gives DUMBBELSS (including urination). A muscarinic antagonist such as trospium blocks the receptors that acetylcholine needs, so it opposes the cholinesterase inhibitor: the antagonist outcompetes the agonist side and defeats its purpose. The same opposition is why atropine reduces the adverse reactions of a cholinesterase inhibitor.",
 quote:"What would be a negative drug-drug interaction? If you add an antagonist to outcompete it, so you're defeating the purpose. ... acetocho estase enzyme antagonist or cholinergic agonist is going to cause the dumbbells, so you need an antagonist that calls the anti-dumbbells.",
 cite:"PCOL-Cholinergic-26s.pdf slides 29–30; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 40; transcript 10/6; transcript 10/8"},

{id:"G2-032", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"t2", skill:"apply",
 concept:"cross-talk-predominant-drive-wins", tags:["in-class"], source:"both",
 stem:"In an anesthetized rat an intravenous bolus of acetylcholine activates the cardiac M2 receptors while, at the same moment, the baroreceptor reflex releases norepinephrine onto the cardiac β1 receptors. Heart rate rises. Which statement is CORRECT?",
 options:[
  {t:"The stronger drive wins the cross-talk", correct:true, why:"M2 (Gi) and β1 (Gs) oppose each other on the same cells; the reflex sympathetic drive is stronger here, so the net result is tachycardia."},
  {t:"Acetylcholine activated β1 directly", correct:false, why:"Acetylcholine binds muscarinic and nicotinic receptors, not β1; the β1 signal came from reflex norepinephrine."},
  {t:"Norepinephrine blocked the M2 receptors", correct:false, why:"Norepinephrine is not a muscarinic antagonist; M2 was activated, but outweighed."},
  {t:"M2 is coupled to Gs in the rat", correct:false, why:"M2 is Gi everywhere; its activation lowers cyclic AMP and slows the heart."},
  {t:"The two signals cancel, so the rate stays constant", correct:false, why:"The rate rose, so the two did not cancel; the sympathetic side predominated."}],
 teach:"In the heart acetylcholine on M2 (Gi, less cyclic AMP) and norepinephrine on β1 (Gs, more cyclic AMP) are cross-talk between opposing second-messenger systems, and whichever side has the predominant tone wins. In the rat the acetylcholine bolus drops blood pressure through endothelial nitric oxide, the baroreceptors shut off the parasympathetic and fire the sympathetic, and that β1 drive overrides the M2 slowing: blood pressure rules.",
 quote:"And whoever has the predominant tone wins that crosstalk, right? ... It is trying to activate the M2s. It is trying to lower the heart rate, but the sympathetics are overriding it because blood pressure rules, right?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 61, 77; transcript 10/7"},

{id:"G2-033", lecture:"L08", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"t1", skill:"tell",
 concept:"succinylcholine-paralysis-order", tags:[], source:"both",
 stem:"Succinylcholine is given. In what order are the muscles paralyzed?",
 options:[
  {t:"Large limbs (legs and arms) → face → diaphragm", correct:true, why:"His order for the depolarizing agent: the large limbs first, then the face, and the diaphragm only if too much is given."},
  {t:"Eyes, jaw and larynx → limbs and trunk → diaphragm", correct:false, why:"That is the order he gave for the curare-like (non-depolarizing) drugs."},
  {t:"Diaphragm → limbs → face", correct:false, why:"The diaphragm is last, which is why an overdose is what stops breathing."},
  {t:"Face → limbs → diaphragm", correct:false, why:"The face comes after the large limbs with succinylcholine."},
  {t:"All muscles at the same moment", correct:false, why:"Not all muscles are created equal: there is an order, with the diaphragm last."}],
 teach:"Succinylcholine opens the Nm channels and paralyzes in an order: the large limbs (legs and arms) first, then the face, and with too high a dose the diaphragm, so the patient stops breathing. For the curare-like competitive antagonists he taught a different order: eyes, jaw and larynx, then limbs and trunk, then the diaphragm. In both cases the diaphragm is last and respiratory paralysis is the danger.",
 quote:"Typically, you start with your large limbs, legs and arms, and then you're going to the face, and then eventually, if you give too much, it can affect the diaphragm, so they stop breathing.",
 note:"The succinylcholine order is in the 10/5 audio only; slide 27 (“Not all muscle are created equal!”) gives the curare-like order (L08-047).",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 20, 27; transcript 10/5"},


/* ---------------- Tier 3: reverse or undo a drug's effect ---------------- */
{id:"G2-034", lecture:"L10", prof:"Gottlieb", tier:"new", level:3, topic:"GAP2", sub:"t3", skill:"apply",
 concept:"hypertensive-crisis-least-likely", tags:["least-likely", "reversal"], source:"both",
 stem:"Which of the following is LEAST likely to produce a hypertensive crisis?",
 options:[
  {t:"Starting prazosin", correct:true, why:"An α1 antagonist dilates the vessels; its first-dose problem is orthostatic hypotension, the opposite of a crisis."},
  {t:"Phenelzine with aged cheese and wine", correct:false, why:"The non-selective MAO inhibitor cannot break down dietary tyramine: the cheese effect, a hypertensive crisis."},
  {t:"Stopping clonidine abruptly", correct:false, why:"Months of suppressed norepinephrine release up-regulate the receptors; cold turkey leaves them all exposed to norepinephrine."},
  {t:"Stopping metoprolol abruptly", correct:false, why:"The antagonist up-regulated β1; sudden discontinuation gives rebound hypertension."}],
 teach:"Three situations he warned about end in a hypertensive crisis: phenelzine with fermented food (tyramine the gut cannot break down), and stopping clonidine or a β blocker abruptly after the receptors have been up-regulated, so the patient must wean off. Starting prazosin goes the other way: the first dose can drop the pressure so far that the patient faints on standing.",
 quote:"You cannot go cold turkey. Because if you go cold turkey, you get what hypertensive crisis, right? ... You got to wean yourself off because if you go cold turkey, you got all these receptors, now norepinephrine is flowing like there's no tomorrow, and you go into a hypertensive crisis, right?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 15, 26, 30, 59; transcript 10/7; transcript 10/6"},

{id:"G2-035", lecture:"L11", prof:"Gottlieb", tier:"new", level:3, ladder:"prazosin", ladderName:"Prazosin, norepinephrine and phenoxybenzamine", topic:"GAP2", sub:"t3", skill:"apply",
 concept:"phenylephrine-outcompete-prazosin", tags:["reversal"], source:"both",
 stem:"A patient pretreated with prazosin receives phenylephrine and shows no rise in blood pressure. Which of the following would restore phenylephrine's pressor response?",
 options:[
  {t:"A much higher dose of phenylephrine", correct:true, why:"Prazosin is a reversible competitive antagonist; enough agonist outcompetes it at α1 and the vasoconstriction returns."},
  {t:"Adding propranolol to remove β2 dilation", correct:false, why:"Phenylephrine has no β2 action to unmask; the response is absent because α1 is occupied."},
  {t:"A low dose of epinephrine instead", correct:false, why:"A low dose of epinephrine acts on β1 and β2 and would dilate, not restore a pressor response."},
  {t:"Nothing: prazosin binds α1 covalently", correct:false, why:"That is phenoxybenzamine; prazosin binds and comes off, so it can be outcompeted."},
  {t:"Adding cocaine to block phenylephrine's reuptake", correct:false, why:"The norepinephrine transporter recycles norepinephrine; it does not change the competition at the receptor."}],
 teach:"Phenylephrine is a pure α1 agonist, so after prazosin there is no β2 action left to show: the pressor response is simply blocked. Because prazosin is reversible, the block is surmountable. A dose of phenylephrine high enough to overpower prazosin outcompetes it at α1 and vasoconstriction returns, the same principle as the 100-fold acetylcholine dose that overcame atropine in the rat.",
 quote:"Right, because they have to give a dose high enough of fenephrine to overpower prazosin and outcompete them. But at these doses, prazosin is winning the war, and you have no activation of any of the receptors.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 50–51; transcript 10/7"},

{id:"G2-036", lecture:"L11", prof:"Gottlieb", tier:"new", level:3, ladder:"epinephrine", ladderName:"Epinephrine: α1 and β2, its blockers, and the EpiPen overdose", topic:"GAP2", sub:"t3", skill:"apply",
 concept:"epinephrine-overdose-mixed-blocker", tags:["reversal", "variant", "exam-cue"], source:"both",
 stem:"Your patient overdosed on an EpiPen and has a very high heart rate and blood pressure. Which single drug would block both the α1 and the β1 part of the overdose at once?",
 options:[
  {t:"Carvedilol", correct:true, why:"A mixed blocker of β1, β2 and α1: it slows the heart and dilates the vessels in one drug, so no order has to be chosen."},
  {t:"Prazosin", correct:false, why:"Blocks only α1: the right first drug if a mixed blocker is not available, but the heart stays fast."},
  {t:"Metoprolol", correct:false, why:"Blocks only β1: given first it slows a heart that still has to pump against clamped arteries."},
  {t:"Phenoxybenzamine", correct:false, why:"Blocks α1 and α2, irreversibly, and nothing in the heart."},
  {t:"Clonidine", correct:false, why:"Suppresses norepinephrine release from nerves; the epinephrine was injected, so the receptors stay fully activated."}],
 teach:"In an epinephrine overdose α1 and β1 predominate: constricted resistance arteries (high afterload) and a racing heart. If only single blockers are at hand, the α1 antagonist goes first so blood keeps flowing, then the β1 blocker. Carvedilol or labetalol block α1 and the β receptors in one drug, so both parts are knocked out at the same time.",
 quote:"Now, if you had an option versus a carvedilol or a labetalol that also blocks the alpha ones and the beta ones, that's a no-brainer. Just knock it out both of them at the same time.",
 note:"A variant of his 10/7 EpiPen poll (PE2-040), which he said he may reuse “in a different shape or form”.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 52, 54; transcript 10/7"},

{id:"G2-037", lecture:"L11", prof:"Gottlieb", tier:"new", level:3, topic:"GAP2", sub:"t3", skill:"apply",
 concept:"beta-blocker-trip-supply", tags:["reversal", "scenario"], source:"both",
 stem:"A patient on metoprolol for months is leaving on a trip and will run out of tablets. What should the patient do?",
 options:[
  {t:"Get a supply from the pharmacist; do not stop", correct:true, why:"Months of β1 blockade up-regulated the receptors; stopping cold turkey leaves them all open to norepinephrine and the pressure rebounds."},
  {t:"Stop now; the receptors are down-regulated, so nothing happens", correct:false, why:"An antagonist up-regulates receptors (more of them), which is exactly why stopping is dangerous."},
  {t:"Switch to propranolol for the trip", correct:false, why:"Any β blocker would need the same continuity; the problem is the gap, not the choice of drug."},
  {t:"Stop and take clonidine instead", correct:false, why:"Clonidine lowers norepinephrine release but does not occupy the extra β1 receptors, and it has its own withdrawal crisis."},
  {t:"Double the dose before leaving, then stop", correct:false, why:"A larger dose does not prevent the rebound once the drug is gone."}],
 teach:"A β blocker lowers the function of the system, so the body makes more β1 receptors (up-regulation). If the drug stops suddenly, all those receptors meet norepinephrine with no blocker: rebound hypertension. The counseling point is to wean off, and never to run out; a patient who forgets the tablets on a trip should call the pharmacist for a supply.",
 quote:"if you're gonna stop your beta blocker or if you go on a trip and you forgot to bring with you, call your pharmacist trying to get a, you know, supply to get you through that process, right?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 59; transcript 10/7"},

{id:"G2-038", lecture:"L09", prof:"Gottlieb", tier:"new", level:3, topic:"GAP2", sub:"t3", skill:"apply",
 concept:"atropine-reverses-muscarinic-agonist-overdose", tags:["reversal"], source:"both",
 stem:"A patient overdoses on bethanechol and has severe bradycardia and diarrhea. Which drug reverses these effects?",
 options:[
  {t:"Atropine", correct:true, why:"A reversible muscarinic antagonist outcompetes bethanechol at M2 (heart) and M3 (gut): the rate rises and the gut quiets."},
  {t:"Neostigmine", correct:false, why:"A cholinesterase inhibitor adds acetylcholine on top of bethanechol: more bradycardia, more diarrhea."},
  {t:"Physostigmine", correct:false, why:"Also a cholinesterase inhibitor; it is the antidote for the opposite poisoning (atropine)."},
  {t:"Pilocarpine", correct:false, why:"A second muscarinic agonist; two agonists add up."},
  {t:"Rocuronium", correct:false, why:"Blocks Nm at skeletal muscle: paralysis, with the heart and gut unchanged."}],
 teach:"Bethanechol is a reversible muscarinic agonist, so its overdose (DUMBBELSS, here bradycardia through M2 and diarrhea through M3) is reversed by giving the opposite: a muscarinic antagonist that outcompetes it. Atropine is listed for the treatment of muscarinic agonist overdose with bradycardia or atrioventricular nodal block. The cholinesterase inhibitors would make it worse.",
 quote:"I can't emphasize enough for you. They're all reversible, so they're all competitive, they're gonna bind, and they're gonna come off. So if we have an overdose, we can always give the opposite to try to outcompete them, OK? ... So atropine, by blocking the parasympathetic tone, you're gonna allow the sympathetic to take over, and it's gonna raise the heart rate.",
 cite:"PCOL-Cholinergic-26s.pdf slides 19–20; transcript 10/5; transcript 10/6"},

{id:"G2-039", lecture:"L09", prof:"Gottlieb", tier:"new", level:3, topic:"GAP2", sub:"t3", skill:"apply",
 concept:"bethanechol-outcompetes-oxybutynin", tags:["reversal"], source:"both",
 stem:"A patient on oxybutynin develops urinary retention. Which of the following would most likely restore bladder emptying?",
 options:[
  {t:"Enough bethanechol to outcompete oxybutynin at M3", correct:true, why:"Both drugs are reversible at the bladder M3; a large enough dose of the agonist displaces the antagonist and the detrusor contracts."},
  {t:"Mirabegron, which activates β3 on the bladder wall", correct:false, why:"β3 relaxes the bladder further and holds more urine: the wrong direction."},
  {t:"Phenylephrine, which tightens the sphincter through α1 and holds the urine", correct:false, why:"A tighter sphincter makes retention worse."},
  {t:"Trospium, a second muscarinic antagonist", correct:false, why:"Two antagonists on M3 relax the bladder even more."},
  {t:"Propranolol", correct:false, why:"The bladder wall has no β1; a β blocker does nothing for emptying."}],
 teach:"Oxybutynin is a reversible muscarinic antagonist on the bladder M3: it relaxes the wall, and too much of it gives retention. Bethanechol is a reversible agonist at the same receptor, so with a high enough dose it outcompetes the antagonist and the bladder contracts again. The same principle restored acetylcholine's response after atropine in the rat with a 100-fold dose.",
 quote:"So by increasing the dose of my agonist, I can outcompete the antagonist if it's needed to be so. ... I can't emphasize enough for you. They're all reversible, so they're all competitive, they're gonna bind, and they're gonna come off.",
 cite:"PCOL-Cholinergic-26s.pdf slides 11–12, 29; transcript 10/7; transcript 10/5"},

/* ---------------- Which statement is INCORRECT ---------------- */
{id:"G2-040", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"beta-blockers-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about the β blockers is INCORRECT?",
 options:[
  {t:"All β blockers block β1", correct:false, why:"A correct statement: selective or not, every β blocker blocks β1 and lowers cardiac output."},
  {t:"Metoprolol is β1 selective", correct:false, why:"A correct statement: metoprolol, atenolol and nebivolol (MAN) are the β1-selective ones."},
  {t:"Propranolol should be avoided in asthma", correct:false, why:"A correct statement: it blocks lung β2 and narrows the airways."},
  {t:"Stopping a β blocker abruptly causes hypotension", correct:true, why:"Stopping abruptly causes rebound hypertension: the up-regulated β1 receptors meet norepinephrine with no blocker."},
  {t:"They reduce renin secretion by blocking β1 in the kidney", correct:false, why:"A correct statement: β1 blockade at the juxtaglomerular cells lowers renin and angiotensin II."}],
 teach:"Every β blocker blocks β1, so all of them lower heart rate, contractility, cardiac output and renin. The differences are selectivity (metoprolol, atenolol, nebivolol spare β2; propranolol and pindolol block β2; carvedilol and labetalol add α1) and the cautions: asthma, nodal dysfunction, insulin-dependent diabetes. Sudden discontinuation causes rebound hypertension from up-regulation, so patients wean off.",
 quote:"You cannot go cold turkey. Because if you go cold turkey, you get what hypertensive crisis, right? You've been up regulating your receptors because that antagonist is lowering the function of the system.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54, 56, 59; transcript 10/7"},

{id:"G2-041", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"clonidine-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about clonidine is INCORRECT?",
 options:[
  {t:"It is an α2 antagonist", correct:true, why:"Clonidine is an α2 agonist; it only behaves like an antagonist of the sympathetic system because the receptor it activates is inhibitory (Gi)."},
  {t:"It lowers sympathetic tone", correct:false, why:"A correct statement: activating the Gi-coupled α2 suppresses norepinephrine release."},
  {t:"It causes dry mouth", correct:false, why:"A correct statement: the sympathetic drive to the salivary gland is suppressed."},
  {t:"It causes sedation", correct:false, why:"A correct statement: its site of action is the central nervous system, which it inhibits."},
  {t:"It must be weaned off", correct:false, why:"A correct statement: abrupt withdrawal after up-regulation causes a hypertensive crisis."}],
 teach:"Clonidine is a selective α2 agonist. α2 is coupled to Gi, so activating it lowers cyclic AMP and suppresses norepinephrine release: less sympathetic tone, vasodilation, bradycardia, lower blood pressure. Its side effects follow (sedation, dry mouth, constipation, hypotension), and stopping it abruptly after the receptors have up-regulated gives a hypertensive crisis.",
 quote:"So clonidine is an agonist that activates the inhibitory pathway. So he's behaving like an antagonist, but he's actually an agonist.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 21, 23, 26; transcript 10/6"},

{id:"G2-042", lecture:"L12", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"ace-inhibitors-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about the angiotensin-converting enzyme (ACE) inhibitors is INCORRECT?",
 options:[
  {t:"They lower plasma angiotensin I", correct:true, why:"Angiotensin I is upstream of the block; it is no longer converted, so it builds up."},
  {t:"They raise bradykinin", correct:false, why:"A correct statement: ACE also breaks down bradykinin, so blocking it raises this vasodilator."},
  {t:"They can cause a dry cough", correct:false, why:"A correct statement: the most common side effect, from accumulated bradykinin."},
  {t:"They can cause hyperkalemia", correct:false, why:"A correct statement: less aldosterone means less potassium wasting."},
  {t:"They lower aldosterone production", correct:false, why:"A correct statement: less angiotensin II, less AT1 activation, less aldosterone."}],
 teach:"An ACE inhibitor blocks the conversion of angiotensin I to angiotensin II, so everything downstream falls (angiotensin II, AT1 and AT2 activation, aldosterone) and everything upstream rises (angiotensin I, renin). Its secondary mechanism is to stop the breakdown of bradykinin, a vasodilator, which also explains the dry cough and angioedema.",
 quote:"It's not gonna decrease angiotensin 1, actually it's gonna increase the left because it's upstream from that, but we'll decrease angiotensin 2. And we'll decrease aldosterone and we'll decrease the activation of A1, right?",
 cite:"PCOL-RAAS_26s.pdf slides 9, 12, 19, 29; transcript 10/8"},

{id:"G2-043", lecture:"L09", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"muscarinic-antagonists-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about the muscarinic antagonists is INCORRECT?",
 options:[
  {t:"They block nicotinic receptors at the neuromuscular junction", correct:true, why:"Atropine and its relatives have affinity only for muscarinic receptors; nicotinic Nm is blocked by the curare-like drugs."},
  {t:"They produce the anti-DUMBBELSS effects: dry mouth, constipation, tachycardia", correct:false, why:"A correct statement: blocking M3 and M2 gives the opposite of the agonist's DUMBBELSS."},
  {t:"They are reversible", correct:false, why:"A correct statement: all of them bind and come off, so they can be outcompeted."},
  {t:"They all have affinity for M3", correct:false, why:"A correct statement: some also bind M1 and M2, but all block M3."},
  {t:"Atropine blocks M1, M2 and M3", correct:false, why:"A correct statement: atropine is the non-selective prototype."}],
 teach:"The muscarinic antagonists (atropine, scopolamine, the “-tropium” inhalers, the bladder drugs) are reversible and most are non-selective, and all of them bind and inhibit M3. Their effects are the anti-DUMBBELSS: dry mouth, constipation, tachycardia, bronchodilation, mydriasis, sedation or hallucinations. None of them touches the nicotinic receptors.",
 quote:"And we have atropine as our non-selective M1, M2, M3 antagonist that is also selected to muscarinics, not nicotinic. That has to be a key distinction that you have to make.",
 cite:"PCOL-Cholinergic-26s.pdf slides 17, 32; transcript 10/6"},

{id:"G2-044", lecture:"L08", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"succinylcholine-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about succinylcholine is INCORRECT?",
 options:[
  {t:"It is a competitive antagonist that acetylcholine can outcompete", correct:true, why:"Succinylcholine is an agonist that opens the Nm channels; the competitive antagonists are the curare-like drugs."},
  {t:"It opens the Nm ion channels", correct:false, why:"A correct statement: it depolarizes the end plate by opening the channels."},
  {t:"It causes paralysis", correct:false, why:"A correct statement: the end plate stays depolarized and cannot reprime, so the muscle cannot contract again."},
  {t:"With longer infusions it reaches the ganglionic Nn receptors and causes hypertension", correct:false, why:"A correct statement: at the ganglia it activates both divisions, with hypertension and arrhythmias."},
  {t:"It can cause hyperkalemia", correct:false, why:"A correct statement: the muscle cells lose potassium, which is why it is avoided in renal-deficient or dehydrated patients."}],
 teach:"Succinylcholine is a depolarizing agent: an agonist that opens the Nm channels at the neuromuscular junction, keeps the end plate depolarized (phase I) and later lodges in the channel (phase II), so the muscle is paralyzed. Being an agonist it cannot be outcompeted by acetylcholine; the curare-like drugs are the competitive, reversible antagonists. Its adverse reactions include hyperkalemia, hypertension and arrhythmias from the ganglia, and muscle pain.",
 quote:"You must know that a sucycholine is an agonist that depolarize or open those ion channels. That's the mechanism of action.",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 19–20, 25; transcript 10/5"},


{id:"G2-045", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"epinephrine-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about epinephrine is INCORRECT?",
 options:[
  {t:"At low doses it acts mainly on α1", correct:true, why:"At low doses epinephrine has the highest affinity for β1 and β2; α1 is reached only as the dose rises."},
  {t:"At low doses it acts on β1 and β2", correct:false, why:"A correct statement: the β receptors bind it best."},
  {t:"At high doses α1 constricts the vessels", correct:false, why:"A correct statement: α1 joins in and overrides the β2 dilation."},
  {t:"After prazosin a high dose dilates the vessels", correct:false, why:"A correct statement: epinephrine reversal, with β2 left unopposed."},
  {t:"Patients on it must be weaned off", correct:false, why:"A correct statement: the agonist down-regulates its receptors."}],
 teach:"Epinephrine binds β1 and β2 first and, as the dose rises, α1 and then α2. So a low dose dilates vessels (β2) and a high dose constricts them (α1 overrides β2). Blocking α1 with prazosin unmasks the β2 dilation at a high dose: epinephrine reversal. Because an infused agonist down-regulates its receptors, patients are weaned off.",
 quote:"At low doses, uh, epinephrine has the highest affinity for the beta 1 and the beta 2 receptor. So if I give a, a little sprinkle of epinephrine, those are the receptors are gonna bind the best to it, OK?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 47–52; transcript 10/7"},

{id:"G2-046", lecture:"L12", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"raas-cascade-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about the renin–angiotensin–aldosterone system (RAAS) is INCORRECT?",
 options:[
  {t:"ACE converts angiotensinogen to angiotensin I", correct:true, why:"Renin does that step; the angiotensin-converting enzyme (ACE) converts angiotensin I to angiotensin II."},
  {t:"Renin from the kidney cleaves angiotensinogen into angiotensin I", correct:false, why:"A correct statement: renin, the rate-limiting enzyme, cuts the liver's long peptide into angiotensin I."},
  {t:"Angiotensin II acts mainly on AT1", correct:false, why:"A correct statement: it has the greatest affinity for AT1."},
  {t:"AT1 is coupled to Gq and AT2 to Gi", correct:false, why:"A correct statement: AT1 raises Ca++ and constricts; AT2 is its physiological antagonist."},
  {t:"Aldosterone is released from the adrenal gland", correct:false, why:"A correct statement: angiotensin II on AT1 releases aldosterone from the adrenal cortex."}],
 teach:"Angiotensinogen (liver) is cleaved by renin (kidney, the rate-limiting enzyme) into angiotensin I; ACE converts angiotensin I to angiotensin II and also breaks down bradykinin. Angiotensin II acts mainly on AT1 (Gq: vasoconstriction, sodium retention, aldosterone release) and less on AT2 (Gi: the physiological antagonist). Aldosterone from the adrenal gland then retains sodium and wastes potassium.",
 quote:"So it so happened that ACE has two functions. One is to convert AG1 into A2. The other one is to break down bradykinin.",
 cite:"PCOL-RAAS_26s.pdf slides 3, 9, 18; transcript 10/8"},

{id:"G2-047", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"prazosin-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about prazosin is INCORRECT?",
 options:[
  {t:"It causes bradycardia", correct:true, why:"Prazosin drops the pressure, and the baroreceptors answer with reflex tachycardia (palpitations), not a slow heart."},
  {t:"It is a selective α1 antagonist", correct:false, why:"A correct statement: about a thousandfold more selective for α1."},
  {t:"It causes orthostatic hypotension", correct:false, why:"A correct statement: the first-dose effect, with syncope on standing."},
  {t:"It can cause headache", correct:false, why:"A correct statement: a common adverse effect of vasodilators."},
  {t:"It worsens nasal congestion", correct:false, why:"A correct statement: relaxing the nasal vessels is the opposite of decongestion."}],
 teach:"Prazosin is a reversible, selective α1 antagonist. Blocking α1 in the arteries and veins lowers total peripheral resistance and blood pressure, with first-dose orthostatic hypotension and syncope, headache, blurred vision and worse nasal congestion. The baroreceptors respond to the fall in pressure with reflex tachycardia, which is why a β blocker is often added.",
 quote:"They also complain of a lot of tachycardia because of the reflex tachycardia that you get from these drugs.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 28–30; transcript 10/6"},

{id:"G2-048", lecture:"L08", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"cholinesterase-inhibitors-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about the cholinesterase inhibitors is INCORRECT?",
 options:[
  {t:"They act anywhere acetylcholine is released", correct:false, why:"A correct statement: the enzyme sits at every cholinergic synapse, so the site of action is wherever acetylcholine is released."},
  {t:"They raise acetylcholine levels", correct:false, why:"A correct statement: with the enzyme blocked, acetylcholine is not broken down."},
  {t:"They produce DUMBBELSS", correct:false, why:"A correct statement: more acetylcholine on the muscarinic receptors."},
  {t:"Neostigmine crosses the blood–brain barrier", correct:true, why:"Neostigmine and pyridostigmine are quaternary amines and do not cross; physostigmine, donepezil and rivastigmine do."},
  {t:"Neostigmine reverses a curare-like block", correct:false, why:"A correct statement: more acetylcholine at the neuromuscular junction outcompetes the reversible antagonist."}],
 teach:"The cholinesterase inhibitors (“-stigmines”, donepezil, the organophosphates) bind acetylcholinesterase and block it, so acetylcholine rises anywhere it is released and DUMBBELSS follows. They differ in distribution: neostigmine and pyridostigmine stay in the periphery (myasthenia gravis, curare reversal), while physostigmine, donepezil and rivastigmine cross the blood–brain barrier.",
 quote:"they can bind to the acetylcholesterase enzyme and block their function. As such, it's going to increase the levels of acetylcholine throughout the body. Uh, some of those may not cross the blood brain barrier like neostigmine. Others will cross really, really well, like donepezil",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 10, 39–41; transcript 10/6"},

{id:"G2-049", lecture:"L12", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"spironolactone-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about spironolactone is INCORRECT?",
 options:[
  {t:"It causes hypokalemia", correct:true, why:"Blocking aldosterone spares potassium, so the risk is hyperkalemia."},
  {t:"It blocks the mineralocorticoid receptor", correct:false, why:"A correct statement: it outcompetes aldosterone at its nuclear receptor."},
  {t:"It is a potassium-sparing diuretic", correct:false, why:"A correct statement: sodium is lost and potassium kept."},
  {t:"It can cause gynecomastia in men", correct:false, why:"A correct statement: it weakly blocks the androgen receptor (not eplerenone)."},
  {t:"It acts in the collecting duct", correct:false, why:"A correct statement: late distal tubule and collecting duct."}],
 teach:"Aldosterone binds the mineralocorticoid receptor (MR) in the late distal tubule and collecting duct and makes more sodium channels and pumps: sodium is kept at the cost of potassium (a potassium-wasting hormone). Spironolactone and eplerenone block the MR, so sodium is lost and potassium spared: potassium-sparing diuretics whose main adverse effect is hyperkalemia. Spironolactone alone adds gynecomastia and impotence.",
 quote:"those drugs are going to be potassium sparing diuretics because you're going to lose the sodium and spare the potassium.",
 cite:"PCOL-RAAS_26s.pdf slides 21–22; transcript 10/8"},

{id:"G2-050", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"inc", skill:"tell",
 concept:"mirabegron-incorrect", tags:["incorrect"], source:"both",
 stem:"Which statement about mirabegron is INCORRECT?",
 options:[
  {t:"It blocks M3 in the bladder", correct:true, why:"Mirabegron activates β3; it is the antimuscarinics (trospium, oxybutynin, solifenacin) that block M3."},
  {t:"It is a β3 agonist", correct:false, why:"A correct statement: the one β3 agonist on the list."},
  {t:"It raises cyclic AMP through Gs", correct:false, why:"A correct statement: β3, like every β receptor, is coupled to Gs."},
  {t:"It relaxes the detrusor muscle", correct:false, why:"A correct statement: the bladder holds more and voiding is prevented."},
  {t:"It lacks the anti-DUMBBELSS effects", correct:false, why:"A correct statement: it does not block muscarinic receptors, so no dry mouth, constipation or blurred vision."}],
 teach:"Mirabegron is a selective β3 agonist. β3 couples to Gs and cyclic AMP, and on the bladder smooth muscle that relaxes the detrusor and increases capacity, so it relieves overactive bladder. Unlike the muscarinic antagonists used for the same purpose it produces no anti-DUMBBELSS effects, but it costs more.",
 quote:"This drug is more selective to the beta 3s in the bladder and thus doesn't have the side effects of the antimuscarinics, right, like atropine or trospium or VESIcare and all those drugs that may cause some of the dumbbells, I'm sorry, may cause some of the anti-dumbbells and thus producing those effects.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/7"},

/* ---------------- If your patient ... ---------------- */
{id:"G2-051", lecture:"L10", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"scen", skill:"apply",
 concept:"hypertension-decongestant-phenylephrine", tags:["scenario"], source:"both",
 stem:"Your patient with hypertension asks for a nasal decongestant. Which drug is most likely to raise his blood pressure?",
 options:[
  {t:"Phenylephrine", correct:true, why:"An α1 agonist: once it reaches the arteries and veins it raises preload and afterload, which is why it is contraindicated in hypertension."},
  {t:"Phenoxybenzamine", correct:false, why:"An α1 and α2 antagonist lowers the pressure and, by relaxing the nasal vessels, makes congestion worse."},
  {t:"Prazosin", correct:false, why:"An α1 antagonist lowers pressure and makes congestion worse."},
  {t:"Clonidine", correct:false, why:"An α2 agonist lowers sympathetic outflow and blood pressure."},
  {t:"Atropine", correct:false, why:"A muscarinic antagonist does not act on the vessels' adrenergic receptors; it does not change blood pressure."}],
 teach:"Phenylephrine decongests by activating α1 (Gq, more Ca++) on the nasal vessels, but the same receptor is on the systemic arteries (afterload) and veins (preload). With repeated use the pressure rises, so an α1 agonist is contraindicated in a patient with high blood pressure, who must use something else.",
 quote:"So, one of the things that uh having uh alpha one agonist is contraindicated is if your patient has high blood pressure. So, they are not supposed to be using very often, if at all, for that purpose.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 18; transcript 10/6"},

{id:"G2-052", lecture:"L11", prof:"Gottlieb", tier:"new", level:3, topic:"GAP2", sub:"scen", skill:"apply",
 concept:"oab-switch-to-mirabegron", tags:["scenario", "reversal"], source:"both",
 stem:"An older patient with an overactive bladder becomes confused on oxybutynin. Which drug relaxes the bladder without blocking muscarinic receptors?",
 options:[
  {t:"Mirabegron", correct:true, why:"A β3 agonist relaxes the detrusor through Gs and cyclic AMP; no muscarinic block, so no sedation or confusion."},
  {t:"Solifenacin", correct:false, why:"More M3 selective and less central than oxybutynin, but still a muscarinic antagonist."},
  {t:"Trospium", correct:false, why:"Another atropine-like muscarinic antagonist."},
  {t:"Bethanechol", correct:false, why:"A muscarinic agonist contracts the bladder: the wrong direction for overactivity."},
  {t:"Dobutamine", correct:false, why:"A β1 agonist for the heart; the bladder's β receptor is β3."}],
 teach:"Oxybutynin blocks M1 as well as M3, and the M1 blockade in the brain gives drowsiness, dizziness and confusion. Two classes relax the bladder: the muscarinic antagonists (all with some anti-DUMBBELSS) and the β3 agonist mirabegron, which relaxes the detrusor through Gs and cyclic AMP without touching muscarinic receptors. Switching to mirabegron removes the muscarinic side effects at a higher cost.",
 quote:"Now this drug that binds and activate the beta 3s in the bladder are becoming first line for bladder overactive activity because you don't get the anti dumbbells associated with that.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/7"},

/* ---------------- Variants of the 10/7 polls (“a different shape or form”) ---------------- */
{id:"G2-053", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"poll", skill:"apply",
 concept:"vasodilation-phenoxybenzamine", tags:["variant", "exam-cue"], source:"both",
 stem:"Which of these drugs is most likely to produce vasodilation?",
 options:[
  {t:"Phenoxybenzamine", correct:true, why:"An irreversible α1 and α2 antagonist: with α1 blocked the arteries and veins relax."},
  {t:"Cocaine", correct:false, why:"Blocks the norepinephrine transporter; more norepinephrine on α1 constricts."},
  {t:"Phenylephrine", correct:false, why:"An α1 agonist: direct vasoconstriction."},
  {t:"Norepinephrine", correct:false, why:"Highest affinity for α1 and β1: constriction and a faster heart."},
  {t:"Dextroamphetamine", correct:false, why:"A releasing agent that increases sympathetic outflow: constriction."}],
 teach:"To pick the vasodilator, place each drug at its receptor on the vessel. The α1 antagonists (prazosin, phenoxybenzamine) take away the predominant constrictor tone and the vessels relax. The α1 agonist (phenylephrine), the catecholamines and the indirect-acting drugs that raise norepinephrine (cocaine, amphetamines) all constrict.",
 quote:"Uh, amphetamine, dextrophetamine or any amphetamine drug, those are gonna increase the sympathetic, those are stimulants, and phenophrine is an alpha-1 agonist, that's gonna cause direct vasoconstriction.",
 note:"A variant of his 10/7 vasodilation poll (PE2-038, key prazosin), which he said he may reuse “in a different shape or form”.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 34, 36, 53; transcript 10/7"},

{id:"G2-054", lecture:"L10", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"poll", skill:"apply",
 concept:"increase-blood-pressure-phenylephrine", tags:["variant", "exam-cue"], source:"both",
 stem:"Which of the following drugs is most likely to increase blood pressure?",
 options:[
  {t:"Phenylephrine", correct:true, why:"An α1 agonist on the arteries and veins: afterload and preload rise."},
  {t:"Prazosin", correct:false, why:"An α1 antagonist: vasodilation, lower pressure."},
  {t:"Clonidine", correct:false, why:"An α2 agonist that suppresses sympathetic outflow: lower pressure."},
  {t:"Atropine", correct:false, why:"A muscarinic antagonist; the vessels' muscarinic receptors are not innervated, so blood pressure is left alone."},
  {t:"Phenoxybenzamine", correct:false, why:"Blocks α1 and α2 irreversibly: the greatest drop in blood pressure, the opposite direction."}],
 teach:"Blood pressure rises when α1 on the arteries and veins is activated (phenylephrine, norepinephrine) or when more norepinephrine reaches it (cocaine). It falls with an α1 antagonist (prazosin) or an α2 agonist (clonidine). A muscarinic antagonist and a neuromuscular blocker have no receptor on the vessel to act on.",
 quote:"Uh, fenophrine is gonna cause an increase in blood pressure. Roqueronio is an NM. Antagonist cause paralysis, shouldn't be causing you to have high blood pressure",
 note:"A mirror of his 10/6 poll “Which of the following drugs is most likely to decrease blood pressure?” (PE2-037, key clonidine).",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 18, 23, 29; transcript 10/6"},

{id:"G2-055", lecture:"L11", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"poll", skill:"apply",
 concept:"twins-narrowed-airways", tags:["variant", "exam-cue"], source:"both", multi:true,
 stem:"Five identical twins run a 5k, each after a different drug: propranolol, metoprolol, carvedilol, carbachol or neostigmine. Which twins are most likely to have narrowed airways? Select all that apply.",
 options:[
  {t:"The propranolol twin", correct:true, why:"A non-selective β blocker blocks lung β2: the airways narrow."},
  {t:"The carvedilol twin", correct:true, why:"Blocks β1, β2 and α1: the β2 block narrows the airways and the α1 block drops the pressure."},
  {t:"The carbachol twin", correct:true, why:"A muscarinic agonist on bronchial M3 (Gq): bronchoconstriction, part of DUMBBELSS."},
  {t:"The neostigmine twin", correct:true, why:"More acetylcholine on bronchial M3: bronchoconstriction, plus the rest of DUMBBELSS."},
  {t:"The metoprolol twin", correct:false, why:"β1 selective: the heart is slowed but lung β2 is spared, so this twin can breathe and comes first."}],
 teach:"The airway narrows when β2 is blocked (propranolol, carvedilol) or when M3 is activated, directly by a muscarinic agonist (carbachol) or by the extra acetylcholine of a cholinesterase inhibitor (neostigmine). Metoprolol blocks only β1, so its lungs stay open; all three β blockers lower cardiac output equally, so the metoprolol twin wins the run.",
 quote:"But at least the metoprolol guy can breathe. His lungs are going to be opening up. He can get more oxygen than everybody else, and thus he can run a little bit faster and further, as propranolol and carvedilol, you block the beta 2s, which means that he can't breathe",
 note:"A select-all variant of his twins poll (PE2-042, key metoprolol); the student's sheet marks that poll “question similar on exam”.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54, 59; PCOL-Cholinergic-26s.pdf slide 13; transcript 10/7"},

{id:"G2-056", lecture:"L09", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"poll", skill:"apply",
 concept:"bladder-contractor-bethanechol", tags:["variant", "exam-cue"], source:"both",
 stem:"Which of the following drugs contracts the bladder smooth muscle, thus increasing urination?",
 options:[
  {t:"Bethanechol", correct:true, why:"A muscarinic agonist on the bladder M3 (Gq): the wall squeezes and the patient urinates."},
  {t:"Mirabegron", correct:false, why:"A β3 agonist relaxes the wall and holds urine."},
  {t:"Trospium", correct:false, why:"A muscarinic antagonist relaxes the bladder: less urination."},
  {t:"Oxybutynin", correct:false, why:"A muscarinic antagonist for overactive bladder: less urgency, less voiding."},
  {t:"Solifenacin", correct:false, why:"The M3-selective bladder antagonist: relaxation."}],
 teach:"Two classes relax the bladder (muscarinic antagonists and the β3 agonist); one class contracts it. A muscarinic agonist such as bethanechol activates M3 (Gq, more Ca++) on the bladder wall, squeezes it and increases urination, which is why it is used for urinary retention.",
 quote:"Remember that if you activate the bladder, you're gonna squeeze the bladder, you're gonna increase urination.",
 note:"The mirror of his 10/7 bladder poll (PE2-041, “relax the bladder smooth muscle, thus decreasing urination”, key mirabegron).",
 cite:"PCOL-Cholinergic-26s.pdf slides 11, 13; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/5"},

/* ---------------- Tracings described in words (one effect each) ---------------- */
{id:"G2-057", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"trace", skill:"figure",
 concept:"tracing-phenylephrine-drug-x-prazosin", tags:["tracing"], source:"both",
 stem:"A blood pressure tracing: phenylephrine raises blood pressure. After drug X is given, the same dose of phenylephrine produces no change in blood pressure. Drug X is most likely:",
 options:[
  {t:"Prazosin", correct:true, why:"An α1 antagonist occupies the receptor phenylephrine needs; with no β2 action to unmask, the response is simply gone."},
  {t:"Propranolol", correct:false, why:"Blocks β receptors; phenylephrine's α1 constriction would be untouched."},
  {t:"Atropine", correct:false, why:"Blocks muscarinic receptors; the vessels' α1 response to phenylephrine stays."},
  {t:"Metoprolol", correct:false, why:"Blocks β1 in the heart; nothing on the vessel is changed."},
  {t:"Cocaine", correct:false, why:"Raises norepinephrine; it would add to the constriction, not abolish it."}],
 teach:"To identify drug X, ask whether it helps or hinders the agonist and which receptor the agonist uses. Phenylephrine works only on α1, so the only drug that abolishes its pressor response is an α1 antagonist. Because phenylephrine has no β2 action there is no reversal, just a flat line, until a much higher dose of phenylephrine outcompetes the reversible prazosin.",
 quote:"And then if I repeat the same experiment and give feuaphrine in the presence of prazosin, which is the antagonist, look what happens. All is blocked.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 50–51; transcript 10/7"},

{id:"G2-058", lecture:"L09", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"trace", skill:"figure",
 concept:"tracing-carbachol-heart-rate-drug-x-atropine", tags:["tracing"], source:"both",
 stem:"A heart rate tracing: carbachol lowers the heart rate. After drug X, the same dose of carbachol no longer changes the heart rate. Drug X is most likely:",
 options:[
  {t:"Atropine", correct:true, why:"A muscarinic antagonist occupies the cardiac M2, so carbachol cannot slow the heart."},
  {t:"Neostigmine", correct:false, why:"More acetylcholine on M2 would deepen the bradycardia, not remove it."},
  {t:"Pilocarpine", correct:false, why:"A second muscarinic agonist would add to carbachol."},
  {t:"Metoprolol", correct:false, why:"Blocks β1; the M2 slowing by carbachol would remain."},
  {t:"Rocuronium", correct:false, why:"Blocks Nm at skeletal muscle; the heart's M2 is untouched."}],
 teach:"Carbachol slows the heart through M2 (Gi, less cyclic AMP). A drug that removes that response without adding to it must block the receptor: atropine, the non-selective muscarinic antagonist. A cholinesterase inhibitor or another agonist would make the bradycardia worse, and the β1 blocker or the neuromuscular blocker has no receptor in this experiment.",
 quote:"Why is carbachol not the best answer? Because that's a muscularic agonist, we're gonna activate the M2s, which are GI, so you're gonna inhibit even more. ... I'm also blocking who the M2s in the heart. So who is unopposed? The sympathetics.",
 cite:"PCOL-Cholinergic-26s.pdf slides 7, 19; transcript 10/6; transcript 10/7"},

{id:"G2-059", lecture:"L08", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"trace", skill:"figure",
 concept:"tracing-ach-skeletal-drug-x-neostigmine", tags:["tracing"], source:"both",
 stem:"A skeletal muscle tracing: acetylcholine produces a contraction. After drug X, the same dose of acetylcholine produces a larger and longer contraction. Drug X is most likely:",
 options:[
  {t:"Neostigmine", correct:true, why:"A cholinesterase inhibitor: acetylcholine is not broken down, stays in the synapse longer and becomes more potent."},
  {t:"Rocuronium", correct:false, why:"A competitive Nm antagonist would shrink or abolish the response."},
  {t:"Succinylcholine", correct:false, why:"A depolarizing agent would give a brief contraction and then no response to acetylcholine."},
  {t:"Atropine", correct:false, why:"Blocks muscarinic receptors; skeletal muscle uses Nm, so nothing changes."},
  {t:"Botulinum toxin", correct:false, why:"Blocks acetylcholine release from the nerve, but the acetylcholine here is applied directly; it would not enlarge the response."}],
 teach:"A drug that makes an agonist's response larger is helping it. At the neuromuscular junction the helper is a cholinesterase inhibitor: with the enzyme blocked, acetylcholine stays in the cleft longer, binds longer and gives a greater contraction (a shift to the left in potency). The two postsynaptic blockers would reduce the response.",
 quote:"Now acetylcholine is gonna stay around that synapse for a much longer period of time and it's gonna make it more potent, thus shifting to the left, right? So it's gonna increase the potency of acetylcholine because you're not gonna break it down.",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 35–36; transcript 10/5"},

{id:"G2-060", lecture:"L11", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"trace", skill:"figure",
 concept:"tracing-albuterol-bronchi-drug-x-propranolol", tags:["tracing"], source:"both",
 stem:"A bronchial smooth muscle tracing: albuterol relaxes the muscle. After drug X, the same dose of albuterol produces no relaxation. Drug X is most likely:",
 options:[
  {t:"Propranolol", correct:true, why:"A non-selective β blocker occupies the bronchial β2 that albuterol needs; the agonist is outcompeted."},
  {t:"Metoprolol", correct:false, why:"β1 selective: lung β2 is left alone, so albuterol still relaxes the muscle."},
  {t:"Ipratropium", correct:false, why:"A muscarinic antagonist relaxes the bronchi itself; it would not oppose albuterol."},
  {t:"Atropine", correct:false, why:"Blocks M3 and dilates; the β2 response to albuterol stays."},
  {t:"Formoterol", correct:false, why:"Another β2 agonist would add to albuterol."}],
 teach:"Albuterol relaxes bronchial smooth muscle through β2 (Gs, more cyclic AMP). A drug that abolishes that relaxation must block β2: propranolol, which is non-selective. Metoprolol spares β2, and the muscarinic antagonists act on the other side of the airway's dual control, so they dilate rather than oppose.",
 quote:"If you have a beta blocker that is non-selective and we're blocking the beta 2, it's going to require more puffs of your saba or your laba to outcompete the beta blocker",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 42, 54, 59; transcript 10/7"},

{id:"G2-061", lecture:"L09", prof:"Gottlieb", tier:"new", level:2, topic:"GAP2", sub:"trace", skill:"figure",
 concept:"tracing-bethanechol-gi-drug-x-neostigmine", tags:["tracing"], source:"both",
 stem:"A gastrointestinal (GI) smooth muscle tracing: bethanechol raises the tone. After drug X, the same dose of bethanechol raises the tone even more. Drug X is most likely:",
 options:[
  {t:"Neostigmine", correct:true, why:"A cholinesterase inhibitor adds acetylcholine on the same M3 receptors: two agonists together, a larger contraction."},
  {t:"Atropine", correct:false, why:"A muscarinic antagonist would abolish the response."},
  {t:"Scopolamine", correct:false, why:"A non-selective muscarinic antagonist: the response would shrink."},
  {t:"Rocuronium", correct:false, why:"Acts on Nm at skeletal muscle, not on the gut's M3; the response would be unchanged."},
  {t:"Oxybutynin", correct:false, why:"A muscarinic antagonist: less contraction, not more."}],
 teach:"Bethanechol contracts gut smooth muscle through M3 (Gq, more Ca++). A drug that makes the response larger is helping the agonist: a cholinesterase inhibitor raises the tissue's own acetylcholine, so two agonists act on the same receptors and the tone rises further. Any muscarinic antagonist would do the opposite, and a neuromuscular blocker has no receptor here.",
 quote:"I know I can remove new stigmine because this increases cetylcholine and would make this even higher because now we have two agonists working on the same receptors, right? So they're going to move to the left, make it more potent.",
 cite:"PCOL-Cholinergic-26s.pdf slides 11, 13; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 36; transcript 10/6"},

/* ---------------- RAAS cascade in his poll form ---------------- */
{id:"G2-062", lecture:"L12", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"raas", skill:"apply",
 concept:"aliskiren-poll-form", tags:["exam-cue"], source:"both",
 stem:"Aliskiren:",
 options:[
  {t:"Decreases AngI plasma level", correct:true, why:"Renin is the rate-limiting enzyme; blocking it stops angiotensinogen being cut, so angiotensin I and everything below it fall."},
  {t:"Increases AngII plasma level", correct:false, why:"Angiotensin II is downstream of renin; it falls."},
  {t:"Increases aldosterone plasma level", correct:false, why:"Less angiotensin II on AT1 means less aldosterone."},
  {t:"Decreases bradykinin plasma level", correct:false, why:"Bradykinin is handled by ACE, which aliskiren does not touch."},
  {t:"Increases the activation of AT1 receptors", correct:false, why:"With less angiotensin II, AT1 activation falls."}],
 teach:"Aliskiren is a reversible, high-affinity inhibitor of renin, the first and rate-limiting enzyme of the cascade. Everything downstream goes down: angiotensin I, angiotensin II, AT1 and AT2 activation and aldosterone; the body compensates upstream by making more renin and angiotensinogen. Unlike an ACE inhibitor it leaves angiotensin I low and bradykinin unchanged.",
 quote:"if I block the renin enzyme, everything downstream from that is gonna go down. Everything upstream from that is gonna go up. And that's how our body is going to compensate.",
 note:"In the form of his 10/8 polls “Lisinopril:” (PE2-054) and “Valsartan:” (PE2-055); he promised “at least 1 to 2 questions on the effects of these drugs in the cascade”.",
 cite:"PCOL-RAAS_26s.pdf slides 8, 29; transcript 10/8"},

{id:"G2-063", lecture:"L12", prof:"Gottlieb", tier:"new", level:1, topic:"GAP2", sub:"raas", skill:"apply",
 concept:"decreases-angiotensin-i-aliskiren", tags:["exam-cue"], source:"both",
 stem:"Which of the following drugs decreases plasma angiotensin I?",
 options:[
  {t:"Aliskiren", correct:true, why:"Blocking renin stops angiotensin I from being made; it is the only block upstream of angiotensin I."},
  {t:"Lisinopril", correct:false, why:"Blocks ACE, downstream of angiotensin I, which is no longer converted and builds up."},
  {t:"Captopril", correct:false, why:"Another ACE inhibitor: angiotensin I rises."},
  {t:"Losartan", correct:false, why:"Blocks AT1 at the end of the cascade; the body makes more of everything upstream, angiotensin I included."},
  {t:"Valsartan", correct:false, why:"Another AT1 blocker: angiotensin I and II rise."}],
 teach:"Where a drug blocks the cascade decides what goes up and what goes down: downstream falls, upstream rises as the body compensates. Only the renin inhibitor sits above angiotensin I, so only aliskiren lowers it. The ACE inhibitors leave angiotensin I unconverted, and the AT1 blockers leave angiotensin I and II both rising.",
 quote:"my body is gonna be compensating by trying to upstream, make more renin, angiotensinogen, and you're gonna have this buildup of angiotensin 1, right, that is not going anywhere in this pathway. So downstream goes down, upstream goes up.",
 cite:"PCOL-RAAS_26s.pdf slides 8, 12–13, 29; transcript 10/8"},

/* ---------------- All of the above ---------------- */
{id:"G2-064", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"allabove", skill:"recall",
 concept:"metoprolol-all-above", tags:["all-above"], source:"both",
 stem:"Which of the following is CORRECT about metoprolol?",
 options:[
  {t:"It is a β1-selective antagonist", correct:false, why:"Correct (one of the MAN drugs), but not the only correct statement."},
  {t:"It lowers heart rate and contractility", correct:false, why:"Correct (every β blocker blocks cardiac β1), but not the only one."},
  {t:"It lowers renin release from the kidney", correct:false, why:"Correct (β1 at the juxtaglomerular cells), but not the only one."},
  {t:"It spares the β2 receptors of the lungs", correct:false, why:"Correct (why it is chosen in asthma), but not the only one."},
  {t:"All the above", correct:true, why:"Every statement follows from a selective β1 antagonist acting on the heart and kidney and leaving β2 alone."}],
 teach:"Metoprolol is a β1-selective antagonist (metoprolol, atenolol, nebivolol: MAN). Blocking cardiac β1 lowers heart rate, contractility and cardiac output; blocking renal β1 lowers renin. Because it spares β2, the lungs are left alone, which is why it is preferred over propranolol in a patient with asthma.",
 quote:"However, metoprolol would be selective to the heart and leave the lungs alone.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 40, 54, 56; transcript 10/7"},

{id:"G2-065", lecture:"L08", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"allabove", skill:"recall",
 concept:"neostigmine-all-above", tags:["all-above"], source:"both",
 stem:"Which of the following is CORRECT about neostigmine?",
 options:[
  {t:"It inhibits acetylcholinesterase", correct:false, why:"Correct (a reversible “-stigmine”), but not the only correct statement."},
  {t:"It does not cross the blood–brain barrier", correct:false, why:"Correct (a quaternary amine), but not the only one."},
  {t:"It can reverse a curare-like block", correct:false, why:"Correct (more acetylcholine outcompetes the reversible antagonist), but not the only one."},
  {t:"It produces DUMBBELSS", correct:false, why:"Correct (more acetylcholine on the muscarinic receptors), but not the only one."},
  {t:"All the above", correct:true, why:"Each statement follows from a peripheral cholinesterase inhibitor that raises acetylcholine wherever it is released."}],
 teach:"Neostigmine is a reversible cholinesterase inhibitor and a quaternary amine, so it raises acetylcholine in the periphery but not in the brain. More acetylcholine at the neuromuscular junction outcompetes a curare-like drug and treats myasthenia gravis; more acetylcholine on muscarinic receptors gives DUMBBELSS as the side effect.",
 quote:"So neo stigamine, which does not cross the blood brain barrier but can increase the levels of acetylcholine in the synapse of your skeletal muscle, would give you a better chance of outcompeting karate and regain some movement for your friend.",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 39, 41; transcript 10/5"},

{id:"G2-066", lecture:"L12", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"allabove", skill:"recall",
 concept:"losartan-all-above", tags:["all-above"], source:"both",
 stem:"Which of the following is CORRECT about losartan?",
 options:[
  {t:"It blocks the AT1 receptor", correct:false, why:"Correct (a “-sartan”), but not the only correct statement."},
  {t:"It increases AT2 receptor activation", correct:false, why:"Correct (the cherry on top: the physiological antagonist is left free), but not the only one."},
  {t:"Plasma angiotensin II rises while it is taken", correct:false, why:"Correct (the body compensates upstream of the block), but not the only one."},
  {t:"It can cause hyperkalemia", correct:false, why:"Correct (less aldosterone), but not the only one."},
  {t:"All the above", correct:true, why:"Every statement follows from a selective AT1 blocker at the end of the cascade."}],
 teach:"Losartan blocks AT1 with 10,000-fold selectivity over AT2. AT1 activation falls (vasodilation, less sodium retention, less aldosterone, so potassium can rise), while angiotensin II accumulates upstream and activates the unblocked AT2, the physiological antagonist that lowers pressure further. It does not raise bradykinin, so the cough is less common than with an ACE inhibitor.",
 quote:"It's not gonna decrease the activation of AT2. Actually it's gonna enhance it",
 cite:"PCOL-RAAS_26s.pdf slides 13–14, 19, 27; transcript 10/8"},

/* ---------------- Drug name, then its class (his “Prazosin:” form) ---------------- */
{id:"G2-067", lecture:"L10", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"colon", skill:"recall",
 concept:"oxymetazoline-colon-moa", tags:["druglist"], source:"both", dupOf:"L10-018",
 stem:"Oxymetazoline:",
 options:[
  {t:"Non-selective α1 and α2 agonist", correct:true, why:"Oxymetazoline activates α1 (constriction) and α2 (relaxation) on the nasal vessels, so it decongests with less constriction than phenylephrine."},
  {t:"Selective α1 agonist", correct:false, why:"That is phenylephrine, which constricts the nasal vessels more."},
  {t:"Selective α2 agonist", correct:false, why:"That is clonidine and the other “-idines”."},
  {t:"Non-selective irreversible α antagonist", correct:false, why:"That is phenoxybenzamine."},
  {t:"Selective α1 agonist used as a nasal decongestant", correct:false, why:"That describes phenylephrine; oxymetazoline is the non-selective one."}],
 teach:"Oxymetazoline is a direct-acting, non-selective α1 and α2 agonist whose site of action is the nasal smooth muscle. α1 (Gq) constricts the nasal vessels and relieves congestion; α2 (Gi) relaxes, so the constriction is less than an α1-selective agonist such as phenylephrine would give. Both are decongestants with the same α1 mechanism; the difference is the α2 part.",
 quote:"We have an option of oxytozoline over here. This is a non-selective alpha 1, alpha 2, so they're gonna kind of, you know, play with each other. Remember, alpha 1s are Q constriction. Alpha 2 is I relaxing, right?",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 9, 19; transcript 10/6"},

{id:"G2-068", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"colon", skill:"recall",
 concept:"carvedilol-colon-moa", tags:["druglist"], source:"both", dupOf:"DL2-073",
 stem:"Carvedilol:",
 options:[
  {t:"Non-selective β1, β2 and α1 antagonist", correct:true, why:"A mixed blocker: it lowers cardiac output through β1 and total peripheral resistance through α1 (and blocks lung β2)."},
  {t:"Selective reversible β1 antagonist", correct:false, why:"That is metoprolol, atenolol or nebivolol."},
  {t:"Non-selective reversible β1 and β2 antagonist", correct:false, why:"That is propranolol; carvedilol adds α1."},
  {t:"Selective α1 antagonist", correct:false, why:"That is prazosin and the other “-osins”."},
  {t:"Partial agonist at β1 and β2", correct:false, why:"That is pindolol."}],
 teach:"Carvedilol and labetalol are the mixed β blockers: they block β1, β2 and α1. Blocking β1 lowers heart rate and contractility, blocking α1 dilates the arteries and veins, so both parts of the mean arterial pressure formula fall. The β2 block means they are avoided in asthma, like propranolol.",
 quote:"Carvedilol is a non-selective beta blocker, right? And carvedilol can not only block the beta ones and the beta 2s, but they can also block the alpha ones.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 7, 54; transcript 10/6"},

{id:"G2-069", lecture:"L08", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"colon", skill:"recall",
 concept:"rocuronium-colon-moa", tags:["druglist"], source:"both", dupOf:"DL2-010",
 stem:"Rocuronium:",
 options:[
  {t:"Competitive reversible Nm antagonist", correct:true, why:"A curare-like (“-cur-”) drug: it stops the nicotinic channel at skeletal muscle from opening, so the muscle is paralyzed."},
  {t:"Depolarizing Nm agonist", correct:false, why:"That is succinylcholine, which opens the channel."},
  {t:"Partial agonist at α4/β2 Nn receptors", correct:false, why:"That is varenicline, in the brain."},
  {t:"Reversible acetylcholinesterase inhibitor", correct:false, why:"That is neostigmine, which reverses rocuronium."},
  {t:"Blocker of acetylcholine release", correct:false, why:"That is botulinum toxin, at the presynaptic terminal."}],
 teach:"Any drug with “-cur-” in its name is curare-like: a competitive, reversible antagonist at the muscle nicotinic (Nm) receptor. It keeps acetylcholine from opening the channel, so the muscle is paralyzed, and because the block is reversible a cholinesterase inhibitor such as neostigmine can outcompete it.",
 quote:"any karate-like drug is what? A competitive, reversible NM antagonist, and by blocking the NM, what are you gonna get? Paralysis, right?",
 cite:"PCOL-NMJ_PCOL_2026s_pptx.pdf slides 19, 27–28; transcript 10/5"},

{id:"G2-070", lecture:"L11", prof:"Gottlieb", tier:"new", topic:"GAP2", sub:"colon", skill:"recall",
 concept:"phenoxybenzamine-colon-moa", tags:["druglist"], source:"both", dupOf:"DL2-058",
 stem:"Phenoxybenzamine:",
 options:[
  {t:"Irreversible α1 and α2 antagonist", correct:true, why:"It forms covalent bonds with both α receptors, so its block cannot be outcompeted."},
  {t:"Selective reversible α1 antagonist", correct:false, why:"That is prazosin."},
  {t:"Non-selective α1 and α2 agonist", correct:false, why:"That is oxymetazoline, the decongestant."},
  {t:"Selective α2 antagonist", correct:false, why:"That is mirtazapine (which also blocks H1, muscarinic and α1)."},
  {t:"Non-selective reversible β1 and β2 antagonist", correct:false, why:"That is propranolol."}],
 teach:"Phenoxybenzamine blocks α1 and α2 irreversibly through covalent bonds, so no amount of norepinephrine can outcompete it: it gives the greatest drop in blood pressure of the α blockers. The α2 block also removes the sympathetic brake on the gut (cramping, diarrhea), and the α1 block gives orthostatic hypotension, reflex tachycardia and miosis.",
 quote:"This is an irreversible non-selective alpha 1, alpha 2 adrenergic receptor antagonist, which means it's going to form covalent bonds.",
 cite:"PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 27, 34–36; transcript 10/7"}
);
